/*CT_START*/const HVP={"martial": [{"axis": "rebel", "dir": 1, "minAge": 15, "text": "隔天我故意哼了一首以前被禁的歌，哼得很大聲。"}, {"axis": "rebel", "dir": -1, "minAge": 12, "maxAge": 17, "need": ["student"], "text": "班導說，解嚴不代表什麼都可以做。我覺得他說得對，把這句話抄進了聯絡簿。"}, {"axis": "rebel", "dir": -1, "minAge": 18, "need": ["working"], "text": "課長交代大家照舊，不該講的話不要講。我點點頭，覺得這樣比較安心。"}, {"axis": "risk", "dir": 1, "minAge": 15, "text": "我跑去書報攤，把以前只敢站著偷翻的雜誌買了一本回家。"}, {"axis": "risk", "dir": -1, "minAge": 15, "need": ["parentsAlive"], "text": "媽媽交代，解嚴歸解嚴，在外面不要亂參加什麼。我說知道啦，其實我本來就沒打算。"}, {"axis": "self", "dir": -1, "minAge": 18, "need": ["working"], "text": "我想的是下個月要寄多少錢回家，弟弟的註冊費還差一點。"}, {"axis": "self", "dir": 1, "minAge": 15, "text": "身邊的人講得口沫橫飛，我在旁邊算這個月的錢，夠不夠買一台新的隨身聽。"}, {"axis": "open", "dir": 1, "minAge": 12, "text": "唱片行開始放一些我以前沒聽過的歌，我站在店裡聽完一整首才走。"}, {"axis": "open", "dir": -1, "minAge": 12, "text": "{elders}說規矩沒了，社會會亂。我覺得有道理，幫他們把茶倒滿。"}, {"axis": "eng", "dir": 1, "minAge": 15, "text": "那天晚上我把收音機開著，一直聽到睡著。"}, {"axis": "eng", "dir": -1, "minAge": 15, "text": "過了好幾天，聽身邊的人一直在講，我才知道原來是這麼大的事。"}], "cck": [{"axis": "rebel", "dir": 1, "minAge": 12, "maxAge": 17, "need": ["student"], "text": "導師要全班寫悼念文。我寫了半頁就寫不下去，被叫去辦公室。"}, {"axis": "rebel", "dir": -1, "minAge": 12, "maxAge": 17, "need": ["student"], "text": "週記上我寫要繼承總統的遺志，老師給了我甲上。"}, {"axis": "rebel", "dir": 1, "minAge": 18, "text": "我心裡有一點點鬆了一口氣，又覺得這樣想好像不太應該。"}, {"axis": "self", "dir": -1, "minAge": 18, "need": ["working"], "text": "我想的是年終會不會延後，過年要給爸媽的紅包還沒著落。"}, {"axis": "self", "dir": 1, "minAge": 15, "text": "那陣子不准放音樂，我戴著耳機偷聽新買的錄音帶，音量開得很小。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我開始每天買兩份不同的報紙，對照著看同一件事怎麼寫。"}, {"axis": "open", "dir": -1, "minAge": 12, "text": "{elders}說，這麼好的總統走了，以後不知道會怎樣。我陪他們看了一整晚的新聞。"}, {"axis": "risk", "dir": -1, "minAge": 15, "text": "我把家裡的報紙疊好收起來。這種時候，最好什麼都不要說。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "朋友說報社在大量招人，問我要不要一起去試試看。我心動了好幾天。"}, {"axis": "eng", "dir": 1, "minAge": 18, "text": "我在想，下一個坐上那個位子的人，講話的口音會不會跟我們一樣。"}, {"axis": "eng", "dir": -1, "minAge": 12, "text": "我只記得那陣子電視很無聊。"}], "missile": [{"axis": "risk", "dir": -1, "minAge": 18, "text": "我去大賣場，看到泡麵的架子空了一半。我拿了兩箱，又放回一箱，覺得自己是不是太緊張了。"}, {"axis": "risk", "dir": 1, "minAge": 20, "text": "股市跌成這樣，我反而跑去號子，買了幾張大家都在拋的股票。"}, {"axis": "self", "dir": -1, "minAge": 25, "need": ["kids", "married"], "text": "晚上我跟另一半小聲討論，如果真的打起來，要先把孩子送去哪裡。"}, {"axis": "self", "dir": 1, "minAge": 20, "text": "身邊的人在講移民。我想的是，如果真的要走，一個人比較好走。"}, {"axis": "rebel", "dir": 1, "minAge": 15, "text": "我跟自己說，偏不要被嚇到。週末我照樣跟朋友出去玩。"}, {"axis": "rebel", "dir": -1, "minAge": 18, "need": ["working"], "text": "主管說不要散播恐慌。我就把那些閒話都當作沒聽到。"}, {"axis": "open", "dir": -1, "minAge": 12, "need": ["parentsAlive"], "text": "媽媽去廟裡拜拜，幫我求了一個平安符，叫我隨身帶著。"}, {"axis": "open", "dir": 1, "minAge": 18, "text": "我熬夜在 BBS 上看大家吵，看到凌晨三點。"}, {"axis": "eng", "dir": -1, "minAge": 18, "text": "午餐時大家在講飛彈，我在想晚上要不要去看電影。"}, {"axis": "eng", "dir": 1, "minAge": 15, "text": "我開始每天看國際新聞，連以前從來不翻的那一版都看。"}, {"axis": "risk", "dir": -1, "minAge": 8, "maxAge": 11, "text": "我問爸爸飛彈會不會掉到家裡。他說不會，可是那天晚上他一直在看新聞。"}], "elect": [{"axis": "rebel", "dir": 1, "minAge": 20, "need": ["parentsAlive"], "text": "投票前一晚，我跟爸爸為了要投誰吵到摔筷子。隔天我們各自出門，誰也沒問誰。"}, {"axis": "rebel", "dir": -1, "minAge": 20, "need": ["parentsAlive"], "text": "爸媽交代要投誰，我就投誰。蓋完章，覺得肩膀上少了一件事。"}, {"axis": "self", "dir": 1, "minAge": 20, "need": ["parentsAlive"], "text": "我本來不打算回戶籍地投票，太遠了。最後還是被媽媽一通電話叫回去。"}, {"axis": "eng", "dir": 1, "minAge": 20, "text": "開票那晚我拿著紙筆跟著電視算票，算得比主播還快。"}, {"axis": "eng", "dir": -1, "minAge": 20, "text": "投完票我就去看電影，連開票都沒看。"}, {"axis": "open", "dir": -1, "minAge": 20, "text": "家裡的老人家拄著拐杖說要自己走去投票，誰扶都不要。我跟在後面走了好久。"}, {"axis": "risk", "dir": -1, "minAge": 20, "text": "投票所外面有人在發面紙和原子筆，我一樣都沒拿，蓋完就趕快回家。"}, {"axis": "rebel", "dir": 1, "minAge": 12, "maxAge": 19, "need": ["parentsAlive"], "text": "我在書桌前貼了一張候選人的貼紙，媽媽看到，叫我撕掉。"}, {"axis": "self", "dir": -1, "minAge": 20, "need": ["kids"], "text": "我抱著孩子去投票，他在投票所裡一直問我在做什麼。我說，在決定以後誰來管我們。"}, {"axis": "open", "dir": 1, "minAge": 12, "maxAge": 19, "need": ["student"], "text": "學校辦了模擬投票，我把每個人的政見都看完才投。"}], "turnover": [{"axis": "rebel", "dir": 1, "minAge": 15, "text": "我第一次覺得，原來上面的人是可以換的。"}, {"axis": "rebel", "dir": -1, "minAge": 15, "text": "這麼大的改變，我心裡有點不安。萬一亂掉了怎麼辦？"}, {"axis": "risk", "dir": 1, "minAge": 18, "need": ["working"], "text": "我跟同事打賭這次會換人做，賭一頓火鍋。我贏了。"}, {"axis": "risk", "dir": -1, "minAge": 20, "text": "我跟家裡說，這陣子錢先不要亂動，看看再說。"}, {"axis": "self", "dir": -1, "minAge": 22, "need": ["kids"], "text": "孩子問我換總統是什麼意思。我想了很久，說就是換一個人來管大家的家。"}, {"axis": "self", "dir": 1, "minAge": 18, "need": ["working"], "text": "隔天辦公室吵得要命，我戴上耳機做自己的事。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我在 BBS 上看大家的開票實況，推文快到看不清楚。"}, {"axis": "open", "dir": -1, "minAge": 12, "need": ["parentsAlive"], "text": "爸爸說，做了五十年都沒換，換了不知道會怎樣。我沒有回答。"}, {"axis": "eng", "dir": -1, "minAge": 12, "text": "我比較在意的是，那晚的鞭炮害我一整晚沒睡好。"}], "319": [{"axis": "rebel", "dir": 1, "minAge": 15, "maxAge": 40, "text": "我在 PTT 跟人吵了一整晚，吵到天亮才發現，自己根本不認識對方。"}, {"axis": "rebel", "dir": -1, "minAge": 15, "text": "家族聚餐時，舅舅一開口講槍擊，阿姨就把碗放下。我低頭扒飯，只想快點吃完。"}, {"axis": "risk", "dir": -1, "minAge": 20, "need": ["working"], "text": "我決定以後不在公司聊政治。中午吃飯，只講天氣和便當。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "我跟朋友賭到底是真是假，賭了一千塊，到現在還沒分出輸贏。"}, {"axis": "self", "dir": 1, "minAge": 15, "maxAge": 30, "text": "大家吵成那樣，我乾脆不看新聞，跑去網咖打 game。"}, {"axis": "self", "dir": -1, "minAge": 25, "need": ["kids"], "text": "孩子問我，為什麼大人吃飯吃到吵起來。我叫他先回房間寫功課。"}, {"axis": "open", "dir": 1, "minAge": 18, "text": "我在網路上看了好幾種說法，每一種都很有道理。看到最後，我什麼都不太相信了。"}, {"axis": "open", "dir": -1, "minAge": 15, "need": ["parentsAlive"], "text": "媽媽說，選舉選到有人中槍，以前想都沒想過。她叫我出門小心一點。"}, {"axis": "eng", "dir": -1, "minAge": 20, "text": "投票那天我睡過頭，沒去投。後來大家吵得那麼兇，我一直不敢跟別人說。"}, {"axis": "self", "dir": -1, "minAge": 15, "maxAge": 18, "need": ["student"], "text": "隔天到學校，班上兩個好朋友為了這件事不講話了。我夾在中間，午餐不知道要跟誰吃。"}], "sun": [{"axis": "self", "dir": 1, "minAge": 15, "maxAge": 40, "text": "臉書整個被洗版。我把幾個一直轉貼的朋友設成不追蹤。"}, {"axis": "rebel", "dir": -1, "minAge": 18, "text": "我覺得有話可以好好說。但我沒有在臉書上講，怕被罵。"}, {"axis": "self", "dir": -1, "minAge": 40, "need": ["kids"], "text": "孩子說要去立法院外面送物資。我叫他不要去，最後還是開車載他到路口，看著他走進人群。"}, {"axis": "open", "dir": -1, "minAge": 15, "maxAge": 30, "text": "{elders}看著電視說，這些孩子不讀書，在那裡睡馬路。我沒說什麼，幫他們轉到八點檔。"}, {"axis": "eng", "dir": -1, "minAge": 22, "maxAge": 35, "need": ["working"], "text": "我每天加班到十點，領的還是 22K。回家在手機上看到學生被水車噴，看了兩分鐘就睡著了。"}, {"axis": "eng", "dir": -1, "minAge": 15, "maxAge": 18, "need": ["student"], "text": "班上有同學請假去現場，回來講得很熱血。我還在煩下個月的模擬考。"}, {"axis": "risk", "dir": -1, "minAge": 18, "text": "我把手機裡的直播關掉，覺得看太多會讓自己不安。"}, {"axis": "risk", "dir": 1, "minAge": 18, "maxAge": 40, "text": "我跟朋友在宵夜攤聊到凌晨，聊以後的台灣會怎樣，好像我們真的能決定什麼。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我第一次把一份懶人包從頭看到尾，然後又去找了反方的說法來看。"}, {"axis": "self", "dir": -1, "minAge": 45, "need": ["kids"], "text": "看著那些跟我孩子差不多大的學生，我一邊替他們擔心，一邊有點羨慕。"}, {"axis": "rebel", "dir": -1, "minAge": 24, "need": ["working"], "text": "公司的 LINE 群組有人轉貼了一份懶人包，主管已讀了。之後就再也沒有人貼了。"}], "tsai": [{"axis": "open", "dir": 1, "minAge": 18, "text": "我在臉書上打了一行字：原來可以。按下發佈之前，刪了又打了好幾次。"}, {"axis": "open", "dir": -1, "minAge": 25, "need": ["working"], "text": "我跟同事說，女人當總統，不知道撐不撐得住。同事白了我一眼，我就沒再說了。"}, {"axis": "open", "dir": -1, "minAge": 18, "maxAge": 45, "need": ["parentsAlive"], "text": "媽媽說女人當總統是好事，可是她沒結婚，以後誰照顧她。我笑了一下，沒有接話。"}, {"axis": "eng", "dir": -1, "minAge": 20, "text": "投完票我就回去補眠，醒來的時候開票已經結束了。"}, {"axis": "eng", "dir": 1, "minAge": 18, "text": "我把開票的畫面截圖存起來，傳給好幾年沒聯絡的同學。"}, {"axis": "self", "dir": -1, "minAge": 28, "need": ["kids"], "text": "孩子指著電視問，女生也可以當總統喔？我說可以啊，說完自己愣了一下。"}, {"axis": "rebel", "dir": 1, "minAge": 20, "maxAge": 30, "text": "我搭了一班塞滿年輕人的客運回老家投票，車上沒有人睡著。"}, {"axis": "risk", "dir": -1, "minAge": 25, "text": "誰當選我沒想太多，只希望房價跟物價不要再漲了。"}, {"axis": "open", "dir": 1, "minAge": 10, "maxAge": 17, "need": ["student"], "text": "隔天老師問大家長大想做什麼。坐我前面的女生舉手說總統，這次沒有人笑。"}], "ssm": [{"axis": "open", "dir": 1, "minAge": 18, "maxAge": 35, "text": "我在 IG 限動放了一面彩虹旗。暗戀的那個人按了愛心，我開心了一整天。"}, {"axis": "open", "dir": 1, "minAge": 20, "maxAge": 45, "text": "大學室友說要結婚了，對象我早就見過好幾次。我在群組裡第一個說要去。"}, {"axis": "rebel", "dir": -1, "minAge": 25, "text": "教會的阿姨傳了好幾則長文到群組。我沒有轉，也沒有退群。"}, {"axis": "self", "dir": -1, "minAge": 55, "need": ["kids"], "text": "我想到孩子三十幾歲了，一直沒帶誰回家。我沒有問，只是那天晚上多煮了一道他愛吃的菜。"}, {"axis": "eng", "dir": -1, "minAge": 18, "text": "手機跳出推播，我滑掉了。下一則是週年慶的消息，我點了進去。"}, {"axis": "risk", "dir": -1, "minAge": 18, "text": "我沒有在網路上表態。這種事，講了只會被罵。"}, {"axis": "self", "dir": 1, "minAge": 18, "text": "別人要跟誰結婚，我覺得跟我沒什麼關係。晚餐要吃什麼比較重要。"}, {"axis": "rebel", "dir": 1, "minAge": 15, "maxAge": 25, "text": "爸媽在飯桌上講得很難聽。我放下筷子回房間，把門關得很大聲。"}], "pelosi": [{"axis": "risk", "dir": -1, "minAge": 20, "text": "我去全聯多買了幾箱水和罐頭，堆在床底下。後來全都放到過期。"}, {"axis": "risk", "dir": 1, "minAge": 25, "need": ["working"], "text": "同事在討論要不要把台股賣掉。我反而加碼，覺得這種時候最便宜。"}, {"axis": "self", "dir": -1, "minAge": 25, "text": "我在家族群組問，如果真的怎樣，大家要在哪裡會合。有人回了一個「？」，就沒有下文了。"}, {"axis": "self", "dir": 1, "minAge": 18, "maxAge": 30, "text": "我去換了新護照，順便查了一下打工度假的年齡限制。"}, {"axis": "rebel", "dir": 1, "minAge": 20, "maxAge": 50, "text": "我報名了民間的急救課。第一堂課，教室裡坐滿了下班趕來的上班族。"}, {"axis": "rebel", "dir": -1, "minAge": 30, "text": "長輩群組傳來一篇「台灣一定會被打」的文章。我沒點開，回了一張早安圖。"}, {"axis": "open", "dir": -1, "minAge": 50, "text": "同學會上我說，以前更緊張的都遇過了。大家點點頭，繼續點菜。"}, {"axis": "eng", "dir": -1, "minAge": 15, "maxAge": 35, "text": "我滑到軍演的新聞，下一則是網紅分手。我點進了下一則。"}, {"axis": "eng", "dir": -1, "minAge": 12, "maxAge": 18, "need": ["student"], "text": "下課時同學在 IG 轉貼飛彈軌跡圖。我按了一個哭臉，下一節是數學小考。"}, {"axis": "open", "dir": 1, "minAge": 25, "need": ["working"], "text": "國外客戶來信問，台灣會不會出事。我回信解釋了很久，寫到最後，覺得像在替自己打氣。"}], "un": [{"axis": "rebel", "dir": 1, "maxAge": 11, "text": "我在作業簿背面畫了一張世界地圖，畫到最後，不知道台灣要放在哪裡。"}, {"axis": "rebel", "dir": -1, "maxAge": 11, "need": ["parentsAlive"], "text": "回家我把口號背給媽媽聽，她說我很乖。"}, {"axis": "risk", "dir": -1, "maxAge": 11, "need": ["parentsAlive"], "text": "那天晚上我問媽媽，我們會不會被趕走。她說不會，叫我快睡。"}, {"axis": "risk", "dir": 1, "maxAge": 11, "text": "下課我跟同學玩打仗遊戲，一邊喊口號一邊往前衝。"}, {"axis": "self", "dir": -1, "maxAge": 11, "need": ["parentsAlive"], "text": "看爸爸一直嘆氣，我把考一百分的考卷拿給他看，他才笑了一下。"}, {"axis": "self", "dir": 1, "maxAge": 11, "text": "我只想知道，這個禮拜的布袋戲會不會照常播。"}, {"axis": "open", "dir": -1, "maxAge": 11, "text": "{elders}說，天塌下來有高個子頂著。我覺得很有道理。"}, {"axis": "open", "dir": 1, "maxAge": 11, "text": "我問老師聯合國在哪裡，老師說在美國。我想，那一定很遠很遠。"}], "japan": [{"axis": "rebel", "dir": 1, "maxAge": 11, "text": "隔天我照樣帶那個日本製的鉛筆盒去學校，誰也沒說什麼。"}, {"axis": "rebel", "dir": -1, "maxAge": 11, "text": "老師說要愛用國貨。我回家就把鉛筆盒上的日本貼紙撕掉了。"}, {"axis": "self", "dir": 1, "maxAge": 11, "text": "我比較擔心的是，以後還吃不吃得到那種日本的牛奶糖。"}, {"axis": "risk", "dir": -1, "maxAge": 11, "text": "大人們一講到日本就壓低聲音。我也學他們，不敢大聲說話。"}, {"axis": "open", "dir": -1, "maxAge": 11, "text": "{elders}說，人跟人之間，翻臉比翻書還快。我聽不太懂，只是點頭。"}, {"axis": "open", "dir": 1, "maxAge": 11, "text": "我還是很喜歡家裡那台日本收音機，每天晚上偷偷轉到很小聲聽。"}, {"axis": "self", "dir": -1, "maxAge": 11, "need": ["parentsAlive"], "text": "媽媽把家裡的日本碗收進櫃子，我幫她一個一個用報紙包起來。"}], "cks": [{"axis": "rebel", "dir": -1, "maxAge": 14, "text": "學校發的黑紗我戴得端端正正，連睡覺前都捨不得拿下來。"}, {"axis": "rebel", "dir": 1, "minAge": 10, "maxAge": 14, "text": "那陣子不能唱歌，我躲在被子裡小聲唱了一首。"}, {"axis": "self", "dir": 1, "maxAge": 11, "need": ["parentsAlive"], "text": "我每天問媽媽，電視什麼時候才會變回彩色的。"}, {"axis": "self", "dir": -1, "minAge": 10, "maxAge": 14, "need": ["parentsAlive"], "text": "爸媽去排隊瞻仰的那天，我留在家裡顧弟弟妹妹，煮了一鍋稀飯。"}, {"axis": "risk", "dir": -1, "maxAge": 14, "text": "大人說這段時間不要亂講話，我連下課都不太敢笑。"}, {"axis": "risk", "dir": 1, "minAge": 10, "maxAge": 14, "text": "同學說要偷溜出去看排隊的人潮，我跟著去了，回家被罵了一頓。"}, {"axis": "open", "dir": -1, "maxAge": 14, "text": "{elders}在神明桌前多點了一炷香，叫我也跟著拜。"}, {"axis": "open", "dir": 1, "minAge": 10, "maxAge": 14, "text": "我在作文裡寫，偉人也會死。老師用紅筆把那一句圈了起來。"}], "usa": [{"axis": "rebel", "dir": 1, "minAge": 12, "text": "老師說美國背叛我們。我舉手問，那以前為什麼要相信他們？全班都安靜了。"}, {"axis": "rebel", "dir": -1, "minAge": 8, "text": "大家都在罵美國。我想到自己的書包是美國牌子的，偷偷把標籤撕掉了。"}, {"axis": "risk", "dir": -1, "minAge": 8, "need": ["parentsAlive"], "text": "我聽見爸媽在房間裡小聲講話，一整晚翻來覆去睡不著。"}, {"axis": "risk", "dir": 1, "minAge": 12, "text": "我想，以後長大要自己去美國看看，那裡到底是什麼樣子。"}, {"axis": "self", "dir": -1, "minAge": 8, "need": ["parentsAlive"], "text": "看爸爸一直嘆氣，吃完晚飯我主動去洗碗。"}, {"axis": "self", "dir": 1, "minAge": 8, "text": "我比較擔心的是，以後還買不買得到美國的口香糖。"}, {"axis": "open", "dir": -1, "minAge": 8, "text": "{elders}說，靠人不如靠自己。我把這句話寫進了作文。"}, {"axis": "open", "dir": 1, "minAge": 12, "text": "我還是每天晚上偷聽電台的英文歌。一個字都聽不懂，但覺得好好聽。"}, {"axis": "eng", "dir": 1, "minAge": 12, "text": "從那天開始，我會把報紙上的國際版剪下來，貼在本子上。"}, {"axis": "eng", "dir": -1, "minAge": 12, "text": "隔天的段考比較重要，我很快就忘了這件事。"}], "formosa": [{"axis": "rebel", "dir": 1, "minAge": 15, "text": "我把報紙上那幾張照片看了很久，想記住他們的臉。"}, {"axis": "rebel", "dir": -1, "minAge": 15, "text": "我覺得好好讀書比較實在，把報紙翻到影劇版。"}, {"axis": "risk", "dir": -1, "minAge": 15, "text": "那陣子我放學就直接回家，路上看到警察都會繞開。"}, {"axis": "risk", "dir": 1, "minAge": 15, "text": "同學偷偷塞一本雜誌給我。我夾在課本裡看完，又傳給下一個人。"}, {"axis": "self", "dir": -1, "minAge": 15, "text": "我只擔心家裡會不會被牽連，晚上一直聽門口有沒有聲音。"}, {"axis": "self", "dir": 1, "minAge": 15, "need": ["student"], "text": "聯考快到了，我告訴自己，這些事以後再想。"}, {"axis": "open", "dir": -1, "minAge": 15, "text": "{elders}說，以前也有人這樣，後來都沒回來。我不敢再問。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我第一次去書店，找報紙以外的東西來看。"}, {"axis": "eng", "dir": 1, "minAge": 15, "text": "我在日記本上寫了一行字，寫完又塗掉。"}, {"axis": "eng", "dir": -1, "minAge": 15, "text": "我那時候比較在意的，是聖誕節要送誰卡片。"}], "lin": [{"axis": "risk", "dir": -1, "minAge": 15, "text": "那天晚上，我把家裡的門鎖檢查了兩次。"}, {"axis": "rebel", "dir": 1, "minAge": 15, "text": "我想不通，為什麼報紙上沒有一個人說是誰做的。"}, {"axis": "self", "dir": -1, "minAge": 15, "text": "回家以後我多看了家人幾眼。媽媽問我幹嘛，我說沒事。"}, {"axis": "self", "dir": 1, "minAge": 15, "text": "我很快就把這件事放到一邊，元宵節的燈籠還沒做完。"}, {"axis": "open", "dir": -1, "minAge": 15, "need": ["parentsAlive"], "text": "媽媽說，大人的事小孩不要問。我就沒有再問。"}, {"axis": "eng", "dir": 1, "minAge": 15, "text": "我把那天的報紙偷偷留了下來，壓在抽屜最底層。"}, {"axis": "rebel", "dir": -1, "minAge": 15, "text": "我告訴自己，不要去想報紙沒寫的事，想了也沒有用。"}, {"axis": "eng", "dir": -1, "minAge": 15, "text": "我只看了標題，就翻到下一頁的電影廣告。"}], "dpp": [{"axis": "risk", "dir": -1, "minAge": 18, "text": "我叮嚀自己，這陣子講話要小心一點。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "我好奇地買了一份寫這件事的雜誌，跟朋友傳著看。"}, {"axis": "rebel", "dir": 1, "minAge": 18, "text": "我心裡替他們捏了一把冷汗，也偷偷有點佩服。"}, {"axis": "rebel", "dir": -1, "minAge": 18, "text": "我覺得現在日子過得好好的，何必搞這些。"}, {"axis": "self", "dir": 1, "minAge": 18, "need": ["working"], "text": "我比較在意的是，下個月的薪水會不會調。"}, {"axis": "self", "dir": -1, "minAge": 18, "need": ["parentsAlive"], "text": "我想到爸媽常講的那些往事，決定先不要在家裡提這件事。"}, {"axis": "open", "dir": 1, "minAge": 18, "text": "我覺得，多一個選擇也不是什麼壞事。"}, {"axis": "open", "dir": -1, "minAge": 18, "text": "{elders}說，這些人是在找麻煩。我沒有反駁。"}], "lily": [{"axis": "rebel", "dir": 1, "minAge": 15, "text": "我把剪下來的野百合照片，貼在書桌前面。"}, {"axis": "rebel", "dir": -1, "minAge": 15, "text": "我覺得學生應該在教室裡，不是在廣場上。"}, {"axis": "risk", "dir": -1, "minAge": 15, "need": ["parentsAlive"], "text": "媽媽打電話來，叫我這陣子不要跟著別人亂跑。我說好。"}, {"axis": "risk", "dir": 1, "minAge": 15, "text": "我在想，如果換成我，會不會也坐在那裡。"}, {"axis": "self", "dir": -1, "minAge": 18, "need": ["working"], "text": "那幾天剛好是家裡最忙的時候，我滿腦子都是工作的事。"}, {"axis": "self", "dir": 1, "minAge": 15, "text": "那陣子我在準備考試，只在睡前看一下新聞。"}, {"axis": "open", "dir": -1, "minAge": 15, "text": "{elders}說，以前的學生哪敢這樣。"}, {"axis": "eng", "dir": -1, "minAge": 20, "text": "那陣子我比較在意的是股票，大家都說還會再漲回來。"}], "red": [{"axis": "rebel", "dir": 1, "minAge": 18, "text": "我覺得不管是誰，做錯事就要負責。"}, {"axis": "rebel", "dir": -1, "minAge": 18, "text": "我覺得這樣一直鬧下去，台灣會被外國人看笑話。"}, {"axis": "risk", "dir": -1, "minAge": 18, "text": "那陣子我刻意不穿紅色的衣服，怕被人誤會。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "我點開直播看了一整晚，看到有人在現場吃便當、睡睡袋。"}, {"axis": "self", "dir": -1, "minAge": 25, "need": ["kids"], "text": "孩子問我紅色是什麼意思。我說是大人在生氣，叫他不要學。"}, {"axis": "self", "dir": 1, "minAge": 18, "text": "每天新聞都一樣，我乾脆把電視關了，去租 DVD 回來看。"}, {"axis": "open", "dir": 1, "minAge": 18, "text": "我在部落格寫了一篇心得，底下的留言吵到一百多則。"}, {"axis": "open", "dir": -1, "minAge": 18, "need": ["parentsAlive"], "text": "媽媽說，總統做到被人這樣罵，真的很難看。"}, {"axis": "eng", "dir": -1, "minAge": 18, "text": "我比較在意的是油價又漲了，騎車上班一個月要多花好幾百。"}], "hung": [{"axis": "rebel", "dir": 1, "minAge": 18, "text": "我想起家裡的男生退伍回來，問什麼都不肯講。"}, {"axis": "risk", "dir": -1, "minAge": 18, "text": "我跟家裡快要入伍的男生說，進去以後什麼都先忍一下，平安回來就好。"}, {"axis": "self", "dir": -1, "minAge": 35, "need": ["kids"], "text": "我想到孩子以後也要當兵，那天晚上一直睡不著。"}, {"axis": "self", "dir": 1, "minAge": 18, "text": "我只轉貼了一次，就繼續滑別的。"}, {"axis": "open", "dir": 1, "minAge": 18, "text": "我第一次把大頭貼換成一片白色。"}, {"axis": "open", "dir": -1, "minAge": 18, "text": "{elders}說，當兵本來就要吃苦。我沒有回話。"}, {"axis": "eng", "dir": -1, "minAge": 22, "maxAge": 30, "text": "我那陣子忙著找工作，履歷投了三十幾封，都沒有回音。"}], "mobil": [{"axis": "rebel", "dir": 1, "minAge": 20, "text": "我想起國小每天唱的那些歌，突然覺得有點好笑。"}, {"axis": "rebel", "dir": -1, "minAge": 20, "text": "我有一點失落，好像一件說好的事被取消了。"}, {"axis": "self", "dir": 1, "minAge": 20, "text": "我比較在意的是，以後的日子會不會比較輕鬆一點。"}, {"axis": "open", "dir": -1, "minAge": 20, "text": "{elders}說，原來喊了一輩子的口號，也可以不用喊。"}, {"axis": "open", "dir": 1, "minAge": 20, "text": "我開始想，對岸的人現在過的到底是什麼樣的日子。"}], "conscript": [{"axis": "self", "dir": -1, "minAge": 40, "need": ["kids"], "text": "我開始在網路上查，哪個新訓中心的伙食比較好。"}, {"axis": "risk", "dir": -1, "minAge": 40, "need": ["kids"], "text": "我叮嚀孩子，進去以後什麼都不要出頭，乖乖做完就好。"}, {"axis": "self", "dir": 1, "maxAge": 19, "text": "我在算，一年以後回來，同學都已經升大二了。"}, {"axis": "rebel", "dir": 1, "maxAge": 19, "text": "我在 Dcard 上跟人吵當兵到底有沒有用，吵到半夜。"}, {"axis": "rebel", "dir": -1, "maxAge": 19, "text": "我想，既然躲不掉，那就認真練吧。"}, {"axis": "risk", "dir": 1, "maxAge": 19, "text": "聽說新的訓練會打比較多靶，我竟然有一點期待。"}], "quake": [{"axis": "risk", "dir": -1, "minAge": 6, "text": "那之後好幾個月，我睡覺都把鞋子放在床邊。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "我請了幾天假，跟著朋友去災區幫忙搬物資。"}, {"axis": "self", "dir": -1, "minAge": 15, "text": "我一直打電話給家人，打到第十幾通終於通了。聽到聲音，我才坐下來。"}, {"axis": "self", "dir": 1, "minAge": 15, "text": "我的第一個念頭是，房間裡那台電腦有沒有摔壞。"}, {"axis": "rebel", "dir": 1, "minAge": 18, "text": "看到新蓋的大樓也倒，我在心裡罵了好久那些偷工減料的人。"}, {"axis": "rebel", "dir": -1, "minAge": 18, "text": "電視上說要團結，我跟著大家去捐血，排了兩個小時。"}, {"axis": "open", "dir": -1, "minAge": 6, "text": "{elders}說這是地牛翻身，叫我們去廟裡拜一拜。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我在網路上看災區的消息，比電視還快。"}, {"axis": "risk", "dir": -1, "maxAge": 11, "need": ["parentsAlive"], "text": "之後只要有一點點搖，我就會跑去抱住媽媽。"}], "sars": [{"axis": "risk", "dir": -1, "minAge": 12, "text": "我把口罩一次買了好幾盒，連睡覺都想戴著。"}, {"axis": "risk", "dir": 1, "minAge": 15, "text": "電影院空空的，我反而覺得是看電影最好的時候，一個人包場。"}, {"axis": "self", "dir": -1, "minAge": 18, "text": "我每天幫家裡的人量體溫，寫在冰箱上的一張紙。"}, {"axis": "self", "dir": 1, "maxAge": 18, "need": ["student"], "text": "學校停課的那幾天，我開心地在家打了三天電動。"}, {"axis": "rebel", "dir": 1, "minAge": 18, "need": ["working"], "text": "公司要大家每天回報體溫。我覺得很煩，常常隨便寫一個數字。"}, {"axis": "rebel", "dir": -1, "minAge": 12, "text": "規定說要量體溫，我每天量兩次，一次都沒漏。"}, {"axis": "open", "dir": -1, "minAge": 12, "need": ["parentsAlive"], "text": "媽媽在門口掛了一把艾草，說可以擋病。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我在網路上找各國的疫情數字，整理成表格貼給朋友看。"}], "covid": [{"axis": "risk", "dir": -1, "minAge": 15, "text": "我在包包、桌上和門口各放了一瓶酒精，出門回來一定先噴。"}, {"axis": "risk", "dir": 1, "minAge": 18, "maxAge": 50, "text": "機票變得好便宜，我心動了好幾天，最後還是沒買。"}, {"axis": "self", "dir": -1, "minAge": 20, "text": "排了好久的隊買到口罩，我先寄了一盒給在外地的家人。"}, {"axis": "self", "dir": 1, "minAge": 15, "maxAge": 45, "text": "出不了國，我把存下來的旅遊基金拿去買了一台 Switch。"}, {"axis": "rebel", "dir": 1, "minAge": 18, "text": "長輩群組傳來一堆偏方，我一則一則回查證的連結，結果被姑姑封鎖了。"}, {"axis": "rebel", "dir": -1, "minAge": 15, "text": "叫大家戴口罩，我就戴；叫大家不要出門，我就待在家。"}, {"axis": "open", "dir": -1, "minAge": 10, "text": "{elders}在神明桌上放了一包口罩，說要給神明加持。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我第一次跟朋友用視訊聚餐，大家對著鏡頭乾杯。"}, {"axis": "eng", "dir": 1, "minAge": 18, "text": "每天下午兩點的記者會，我一場都沒漏。"}, {"axis": "eng", "dir": -1, "minAge": 15, "text": "我很快就不看確診數字了，看了只會更煩。"}], "lv3": [{"axis": "risk", "dir": -1, "minAge": 15, "text": "我叫外送放在門口，等外送員走遠了才開門。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "我趁人少，一個人騎車去山上兜風，整條路只有我。"}, {"axis": "self", "dir": -1, "minAge": 25, "text": "我每天打電話給家裡的長輩，叫他們不要出門，菜我買好放在門口。"}, {"axis": "self", "dir": 1, "minAge": 18, "need": ["working"], "text": "不用通勤，我每天多睡一個小時，覺得其實也不錯。"}, {"axis": "rebel", "dir": 1, "minAge": 18, "text": "我在網路上罵疫苗怎麼還不來，罵完又去搶預約。"}, {"axis": "rebel", "dir": -1, "minAge": 12, "text": "每一家店門口的 QR code，我都乖乖掃。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我開始學做麵包。失敗了五次，第六次終於像樣了。"}, {"axis": "open", "dir": -1, "minAge": 12, "need": ["parentsAlive"], "text": "媽媽每天早上在神明桌前多念一段經，我站在旁邊跟著合掌。"}], "lehman": [{"axis": "risk", "dir": -1, "minAge": 18, "need": ["working"], "text": "我開始每天帶便當，連一杯咖啡都捨不得買。"}, {"axis": "risk", "dir": 1, "minAge": 22, "need": ["working"], "text": "大家都在賣股票，我反而開始每個月存一點進去。"}, {"axis": "self", "dir": -1, "minAge": 30, "need": ["kids"], "text": "我把孩子的補習班停了一個，跟他說先休息一下。"}, {"axis": "self", "dir": 1, "minAge": 20, "maxAge": 40, "text": "我心想，反正我一個人，大不了回老家住。"}, {"axis": "rebel", "dir": 1, "minAge": 20, "need": ["working"], "text": "公司說要共體時艱，我跟同事在茶水間罵了整個午休。"}, {"axis": "rebel", "dir": -1, "minAge": 20, "need": ["working"], "text": "主管說要共體時艱，我第一個簽了減薪同意書。"}, {"axis": "open", "dir": 1, "minAge": 20, "text": "我晚上去上了一堂電腦課，想說多學一點總是好的。"}, {"axis": "open", "dir": -1, "minAge": 20, "text": "{elders}說，以前更苦都過來了。這句話我聽了好幾遍。"}], "nhi": [{"axis": "risk", "dir": -1, "minAge": 12, "text": "我把健保卡收在皮夾最裡面那一層，怕弄丟。"}, {"axis": "self", "dir": 1, "minAge": 15, "text": "有了健保卡，我第一件事就是去看那顆痛了好久的牙。"}, {"axis": "self", "dir": -1, "minAge": 18, "text": "我先帶{elders}去辦卡，排了一整個早上。"}, {"axis": "rebel", "dir": 1, "minAge": 20, "text": "保費單寄來，我看了很久，覺得怎麼又多一筆要繳的錢。"}, {"axis": "open", "dir": -1, "minAge": 12, "need": ["parentsAlive"], "text": "媽媽還是習慣先去藥房問老闆，說醫生開的藥太重。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "我想，有了這張卡，以後摔車受傷也不怕了。騎車騎得比以前還快。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "醫生問診的時候，我把在雜誌上看到的健康知識問了一遍，他笑著一一回答。"}], "stock": [{"axis": "self", "dir": -1, "minAge": 20, "text": "我想到家裡還有一筆跟會的錢，晚上偷偷算了好幾次。"}, {"axis": "self", "dir": 1, "minAge": 20, "text": "我想的是，還好那台機車是用現金買的。"}, {"axis": "open", "dir": -1, "minAge": 20, "text": "{elders}說，錢要存在銀行才安全，股票就是賭博。"}, {"axis": "open", "dir": 1, "minAge": 20, "text": "我開始去書店翻理財的書，想弄懂到底發生了什麼事。"}, {"axis": "rebel", "dir": 1, "minAge": 20, "text": "號子裡有人在罵政府，罵到後來，大家都安靜下來看著盤。"}], "dajia": [{"axis": "self", "dir": -1, "minAge": 18, "need": ["working", "parentsAlive"], "text": "我把薪水大部分交給媽媽，她拿去跟會。"}, {"axis": "self", "dir": 1, "minAge": 18, "text": "我用年終買了一台錄放影機，每天晚上租片回來看。"}, {"axis": "open", "dir": -1, "minAge": 18, "text": "{elders}說，賺太快的錢，去得也快。"}, {"axis": "open", "dir": 1, "minAge": 18, "text": "我開始去西餐廳吃牛排，覺得自己好像也跟上了。"}], "asia": [{"axis": "risk", "dir": -1, "minAge": 20, "text": "沒有年終，我把出國的計畫延到明年。"}, {"axis": "risk", "dir": 1, "minAge": 20, "text": "我跟同事說，這種時候才要換工作。說完我自己也有點心虛。"}, {"axis": "self", "dir": -1, "minAge": 20, "need": ["parentsAlive"], "text": "過年要給爸媽的紅包，我少包了一點，心裡很過意不去。"}, {"axis": "self", "dir": 1, "minAge": 20, "text": "我覺得還好，反正我本來就沒存什麼錢。"}, {"axis": "open", "dir": 1, "minAge": 20, "text": "我開始看英文的財經新聞，雖然一半看不懂。"}, {"axis": "rebel", "dir": 1, "minAge": 20, "text": "老闆開著新車來上班，跟大家說今年沒有年終。我在心裡翻了一個白眼。"}], "morakot": [{"axis": "risk", "dir": -1, "minAge": 15, "text": "那之後，只要颱風警報一發布，我就先去買好三天份的水和泡麵。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "我跟著朋友報名去災區清淤泥，雨鞋陷進泥巴裡拔不出來。"}, {"axis": "self", "dir": -1, "minAge": 12, "text": "我把衣櫃整理了一大袋捐出去，連自己最喜歡的那件外套也放了進去。"}, {"axis": "self", "dir": 1, "minAge": 12, "text": "新聞看了幾天就看不下去了，我轉去看綜藝節目。"}, {"axis": "rebel", "dir": 1, "minAge": 18, "text": "看到官員還在說要評估，我氣到把遙控器摔在沙發上。"}, {"axis": "rebel", "dir": -1, "minAge": 18, "text": "我想，政府應該有在處理吧，我們就做好自己的事。"}, {"axis": "open", "dir": -1, "minAge": 12, "text": "{elders}說，山是有脾氣的，人不能跟山搶地。"}, {"axis": "open", "dir": 1, "minAge": 15, "text": "我在 PTT 上看到網友自己整理的災情地圖，比新聞還快。"}], "weekend": [{"axis": "risk", "dir": 1, "minAge": 18, "text": "我開始每個週末都往外跑，一年下來去了好多以前沒去過的地方。"}, {"axis": "risk", "dir": -1, "minAge": 18, "text": "多出來的那一天，我拿去兼差。"}, {"axis": "self", "dir": -1, "minAge": 18, "need": ["parentsAlive"], "text": "星期六我都回家陪爸媽吃飯，媽媽每次都煮一大桌。"}, {"axis": "self", "dir": 1, "minAge": 18, "text": "星期六我睡到自然醒，第一次覺得一個禮拜有兩天是自己的。"}, {"axis": "open", "dir": 1, "minAge": 18, "text": "我報名了週末的日文課，想說總有一天用得到。"}, {"axis": "open", "dir": -1, "minAge": 18, "text": "{elders}說，以前一個禮拜做七天，哪有在休息的。"}, {"axis": "rebel", "dir": 1, "minAge": 18, "text": "公司說星期六還是可以「自願」來加班。我一次都沒去。"}], "phone": [{"axis": "risk", "dir": -1, "minAge": 15, "text": "我怕被詐騙，什麼 App 都不敢裝。"}, {"axis": "risk", "dir": 1, "minAge": 12, "text": "我第一天就下載了二十幾個 App，玩到手機發燙。"}, {"axis": "self", "dir": -1, "minAge": 18, "text": "我教家裡的長輩用 LINE，教了十幾次，他們還是只會傳貼圖。"}, {"axis": "self", "dir": 1, "minAge": 12, "text": "我開始在吃飯前先拍照，拍完才動筷子。"}, {"axis": "open", "dir": -1, "minAge": 15, "text": "我還是比較喜歡打電話，打字太慢了。"}, {"axis": "open", "dir": 1, "minAge": 12, "text": "我開了一個 IG 帳號，第一張照片拍的是早餐。"}, {"axis": "rebel", "dir": 1, "minAge": 20, "need": ["working"], "text": "公司開了 LINE 群組，主管半夜也在傳訊息。我故意等到隔天早上才回。"}], "wang": [{"axis": "risk", "dir": 1, "minAge": 15, "text": "我跟朋友賭下一場會不會贏，賭了一杯飲料。"}, {"axis": "self", "dir": -1, "minAge": 12, "need": ["parentsAlive"], "text": "爸爸以前從來不看棒球，現在每天早上都叫我陪他看。"}, {"axis": "open", "dir": -1, "minAge": 12, "text": "{elders}說，打球打到外國去，真的是替台灣人爭氣。"}, {"axis": "open", "dir": 1, "minAge": 12, "text": "我去買了一頂洋基的帽子，戴了好幾個月。"}, {"axis": "self", "dir": 1, "minAge": 12, "text": "店裡太吵了，我拿了早餐就外帶走人。"}], "cape7": [{"axis": "open", "dir": 1, "minAge": 12, "text": "回家以後，我把〈野玫瑰〉的原曲找出來，聽了好幾遍。"}, {"axis": "open", "dir": -1, "minAge": 12, "text": "看到片尾老人家在台上唱歌，我想到{elders}，眼眶一熱。"}, {"axis": "self", "dir": -1, "minAge": 18, "text": "我帶{elders}去看。他們看到一半睡著了，醒來說很好看。"}, {"axis": "self", "dir": 1, "minAge": 18, "text": "我一個人去看午夜場，散場的時候，突然好想回老家。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "看完以後我一直在想，是不是也該回家鄉做點什麼。"}, {"axis": "rebel", "dir": 1, "minAge": 15, "text": "片中那句抱怨這裡什麼都沒有的台詞，說到我心裡去了。"}], "fb": [{"axis": "self", "dir": -1, "minAge": 15, "need": ["parentsAlive"], "text": "我加了媽媽好友。她每張照片都按讚，還留言叫我多穿一點。"}, {"axis": "self", "dir": 1, "minAge": 15, "need": ["parentsAlive"], "text": "我把媽媽設成看不到我的動態。"}, {"axis": "risk", "dir": 1, "minAge": 18, "text": "我搜尋到很久沒聯絡的初戀，猶豫了三天，才按下加好友。"}, {"axis": "risk", "dir": -1, "minAge": 15, "text": "我的帳號只放了一張風景照，名字也用英文。"}, {"axis": "open", "dir": -1, "minAge": 15, "text": "把生活放到網路上給人看，我覺得很奇怪。帳號開了就沒再登入。"}], "meteor": [{"axis": "self", "dir": 1, "minAge": 10, "text": "我把 F4 的海報貼滿了房間的牆。"}, {"axis": "rebel", "dir": 1, "minAge": 10, "need": ["parentsAlive"], "text": "媽媽說這種戲會教壞小孩，我就躲在房間偷看重播。"}, {"axis": "rebel", "dir": -1, "minAge": 10, "need": ["parentsAlive"], "text": "媽媽說這種戲會教壞小孩，我就沒再看了。"}, {"axis": "risk", "dir": 1, "minAge": 12, "maxAge": 18, "need": ["student"], "text": "我學道明寺把頭髮抓得好高，被教官叫去剪掉。"}, {"axis": "self", "dir": -1, "minAge": 10, "text": "我本來是陪妹妹看的，結果看得比她還入迷。"}], "ai": [{"axis": "risk", "dir": -1, "maxAge": 22, "need": ["student"], "text": "我還是自己寫，怕被老師抓到。"}, {"axis": "risk", "dir": 1, "minAge": 12, "text": "我試了各種用法，最後把一整個禮拜的報告都丟給它寫。"}, {"axis": "self", "dir": -1, "minAge": 30, "need": ["kids"], "text": "我用 AI 幫孩子查功課，結果它講錯了，被孩子抓到。"}, {"axis": "self", "dir": 1, "minAge": 25, "text": "我幫家裡的長輩把手機設定好，叫他們有問題先問它，不要一直打給我。"}, {"axis": "rebel", "dir": 1, "minAge": 22, "need": ["working"], "text": "主管說不會用 AI 的人會被淘汰。我在心裡想：「那你先被淘汰好了。」"}, {"axis": "rebel", "dir": -1, "minAge": 22, "need": ["working"], "text": "公司規定要用，我就每天乖乖用，雖然覺得自己寫還比較快。"}, {"axis": "open", "dir": -1, "minAge": 15, "text": "我覺得機器寫出來的東西沒有溫度，看了就是不舒服。"}, {"axis": "open", "dir": 1, "minAge": 12, "text": "我開始用 AI 畫圖，一個晚上畫了一百張，存滿了手機。"}], "p_ai": [{"axis": "risk", "dir": -1, "minAge": 22, "text": "我把每個月的開銷砍了一半，先存起來再說。"}, {"axis": "risk", "dir": 1, "minAge": 22, "text": "我開始在下班後學做木工，想說手做的東西總不會被取代。"}, {"axis": "self", "dir": -1, "minAge": 30, "need": ["kids"], "text": "我想到孩子以後要做什麼工作，越想越不知道該叫他讀什麼。"}, {"axis": "self", "dir": 1, "minAge": 22, "text": "我開始想，如果工作不需要我了，我自己到底想做什麼。"}, {"axis": "open", "dir": -1, "minAge": 30, "text": "我想起長輩說過，有一技之長就餓不死。這句話我以前覺得很老套。"}, {"axis": "rebel", "dir": 1, "minAge": 22, "need": ["working"], "text": "我跟主管說，我不想去那個完全不熟的位置。他沉默了很久。"}], "p_pension": [{"axis": "risk", "dir": -1, "minAge": 50, "text": "我把原本打算換車的錢，轉進了定存。"}, {"axis": "risk", "dir": 1, "minAge": 50, "text": "我開始研究 ETF，每個月多扣一點。"}, {"axis": "self", "dir": -1, "minAge": 50, "need": ["kids"], "text": "我跟孩子說：「以後不要指望我留什麼給你們了。」說完我們都笑得很勉強。"}, {"axis": "self", "dir": 1, "minAge": 50, "text": "我想，反正錢是自己的，能花的時候就先花吧。"}, {"axis": "open", "dir": -1, "minAge": 50, "text": "我想起以前長輩說，錢要存在自己身上。現在才懂。"}, {"axis": "rebel", "dir": 1, "minAge": 50, "text": "我在新聞底下留言罵了一大串。按下送出以後，心情也沒有比較好。"}], "tariff": [{"axis": "risk", "dir": -1, "minAge": 20, "need": ["working"], "text": "我開始把每個月的薪水分成好幾份，先存下三個月的生活費。"}, {"axis": "risk", "dir": 1, "minAge": 20, "need": ["working"], "text": "我默默更新了履歷，想趁還沒被裁之前先找好退路。"}, {"axis": "self", "dir": -1, "minAge": 30, "need": ["kids"], "text": "我想到房貸跟孩子的學費，晚上翻來覆去睡不著。"}, {"axis": "self", "dir": 1, "minAge": 20, "maxAge": 40, "text": "我心想，大不了換個行業，反正我還年輕。"}]};const EC=[{"id": "bcg", "minAge": 0, "maxAge": 0, "by": [1961, 1985], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.8, "cat": "健康", "tone": "neutral", "text": "我出生沒多久，就在衛生所打了卡介苗。護士在我左手臂扎了一針，我哭到整張臉都紅了。後來那裡留下一個小小的疤。", "group": "vax"}, {"id": "bcg_hosp", "minAge": 0, "maxAge": 0, "by": [1986, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.6, "cat": "健康", "tone": "neutral", "text": "我在醫院打了卡介苗。左手臂上鼓起一個小紅點，我哭了兩聲，就在媽媽懷裡睡著了。", "group": "vax"}, {"id": "polio_drops", "minAge": 0, "maxAge": 1, "by": [1966, 1985], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.6, "cat": "健康", "tone": "neutral", "text": "護士用小湯匙把一點甜甜的藥水滴進我嘴裡，是小兒麻痺的疫苗。我舔了舔嘴唇，還想要。", "group": "vax"}, {"id": "polio_sick", "minAge": 1, "maxAge": 3, "by": [1961, 1965], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": false, "weight": 0.12, "cat": "健康", "tone": "bad", "text": "我發了好幾天高燒。燒退以後，我的右腳就站不穩了。{elders}揹著我，一間廟一間廟去拜。", "fx": {"health": -12}, "flag": "polio"}, {"id": "polio_1982", "minAge": 1, "maxAge": 5, "by": [1977, 1981], "y": [1982], "months": [6, 7], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.5, "cat": "健康", "tone": "neutral", "text": "衛生所前面排了好長的隊，大人抱著小孩等著吃小兒麻痺疫苗。排隊的大人都在講，隔壁村有小孩發燒以後腳就不能動了。我排在隊伍裡，手上拿著一支冰棒，什麼都不怕。"}, {"id": "hbv", "minAge": 0, "maxAge": 0, "by": [1986, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.7, "cat": "健康", "tone": "neutral", "text": "我一出生就打了 B 肝疫苗。之後還有好幾劑，媽媽把日期寫在兒童健康手冊上，用紅筆圈起來。", "group": "vax", "hbv": true}, {"id": "measles", "minAge": 2, "maxAge": 5, "by": [1961, 1977], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.8, "cat": "健康", "tone": "bad", "text": "我出麻疹，全身起紅疹，燒了好幾天。{elders}拿布把窗戶遮起來，說不能見光。我躺在暗暗的房間裡，聽外面的小孩在玩，很想出去。", "fx": {"health": -2}}, {"id": "chickenpox", "minAge": 3, "maxAge": 6, "by": [1961, 2003], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.8, "cat": "健康", "tone": "bad", "text": "我出水痘，全身一顆一顆的。媽媽把襪子套在我手上當手套，不讓我抓。我癢到睡不著，一直哭。"}, {"id": "je_vax", "minAge": 1, "maxAge": 3, "by": [1968, 2010], "y": null, "months": [3, 4, 5], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.5, "cat": "健康", "tone": "neutral", "text": "春天我打了日本腦炎疫苗。打完那天晚上有點發燒，我整晚黏在媽媽身上，誰都不給抱。", "group": "vax"}, {"id": "worms", "minAge": 3, "maxAge": 6, "by": [1961, 1978], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": false, "weight": 0.6, "cat": "健康", "tone": "neutral", "text": "我肚子痛了好幾天，被帶去衛生所。醫生給我吃了打蟲藥。隔天上廁所的時候，我嚇得大叫。"}, {"id": "clinic_poor", "minAge": 1, "maxAge": 6, "by": [1961, 1990], "y": [1961, 1962, 1963, 1964, 1965, 1966, 1967, 1968, 1969, 1970, 1971, 1972, 1973, 1974, 1975, 1976, 1977, 1978, 1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1992, 1993, 1994], "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.6, "cat": "健康", "tone": "bad", "text": "我半夜發高燒。媽媽抱著我在門口站了很久，才決定去敲診所的門。看一次醫生，要花掉家裡好幾天的菜錢。我在她懷裡燒得迷迷糊糊。", "inc": "低"}, {"id": "clinic_nhi", "minAge": 1, "maxAge": 6, "by": [1961, 2010], "y": [1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016], "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.6, "cat": "健康", "tone": "neutral", "text": "我又感冒了。小兒科的候診室擠滿了哭鬧的小孩，健保卡上又蓋了一格。醫生給我一支棒棒糖，我就不哭了。"}, {"id": "ev71_1998", "minAge": 0, "maxAge": 5, "by": [1993, 1998], "y": [1998], "months": [5, 6], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.5, "cat": "健康", "tone": "bad", "text": "那陣子大人一直在講腸病毒，家裡門口擺了一瓶漂白水。我喉嚨長了好幾顆水泡，吞口水都痛，連最愛的布丁都吃不下。", "fx": {"health": -2}}, {"id": "ev_closure", "minAge": 3, "maxAge": 5, "by": [1999, 2010], "y": [2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016], "months": [4, 5, 6, 7], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1, "cat": "健康", "tone": "neutral", "text": "班上第二個小朋友得了腸病毒，整班停課一個禮拜。我很開心不用上學，媽媽卻一直在打電話找人帶我。"}, {"id": "dengue_1988", "minAge": 0, "maxAge": 6, "by": [1961, 2010], "y": [1987, 1988], "months": [8, 9, 10, 11], "region": null, "county": ["高雄市", "高雄縣", "屏東縣"], "eth": null, "pjob": null, "urban": null, "weight": 1.5, "cat": "健康", "tone": "neutral", "text": "里長騎著機車在巷子裡廣播，要大家把花盆底下的積水倒掉。噴藥車開過來，整條街都是白煙。我躲在門後面，捏著鼻子看。"}, {"id": "dengue_2015", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": [2014, 2015], "months": [8, 9, 10, 11], "region": null, "county": ["台南市", "台南縣", "高雄市", "高雄縣"], "eth": null, "pjob": null, "urban": null, "weight": 1.5, "cat": "健康", "tone": "neutral", "text": "我在公園玩回來，腿上多了好幾個蚊子包。媽媽一個一個檢查，晚上又幫我量了兩次體溫。電視每天都在報登革熱又多了幾個人。"}, {"id": "sars_baby", "minAge": 0, "maxAge": 2, "by": [1961, 2010], "y": [2003], "months": [4, 5, 6], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.5, "cat": "健康", "tone": "neutral", "text": "大人出門都戴著口罩。{elders}來看我，在門口先用酒精擦了好幾遍手，才敢把我抱起來。"}, {"id": "sars_kinder", "minAge": 3, "maxAge": 4, "by": [1961, 2010], "y": [2003], "months": [4, 5, 6], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.5, "cat": "健康", "tone": "neutral", "text": "每天早上，幼稚園老師在門口幫每個人量額溫。我也戴了一個口罩，大到遮住半張臉，一直往下滑。"}, {"id": "h1n1", "minAge": 1, "maxAge": 6, "by": [1961, 2010], "y": [2009], "months": [11, 12], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1, "cat": "健康", "tone": "neutral", "text": "我打了生平第一支流感疫苗。我一邊哭一邊拿到一張貼紙，出了診所就忘記哭了。"}, {"id": "milk_2008", "minAge": 0, "maxAge": 3, "by": [1961, 2010], "y": [2008], "months": [9, 10], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.5, "cat": "健康", "tone": "neutral", "text": "新聞說有奶粉驗出三聚氰胺。媽媽把家裡的奶粉罐翻過來，一個字一個字對產地。那天晚上，我喝的是米漿。"}, {"id": "shoujing", "minAge": 2, "maxAge": 5, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": ["閩南", "客家"], "pjob": null, "urban": null, "weight": 0.8, "cat": "健康", "tone": "neutral", "text": "我被隔壁的大狗嚇到，晚上一直哭醒。{elders}帶我去廟裡收驚，廟婆拿著一碗米在我頭上繞圈，嘴裡念念有詞。那天晚上我一覺到天亮。"}, {"id": "allergy", "minAge": 2, "maxAge": 6, "by": [1990, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": true, "weight": 0.6, "cat": "健康", "tone": "neutral", "text": "我一換季就鼻子過敏，整晚用嘴巴呼吸。媽媽在床頭放了一台空氣清淨機，嗡嗡嗡的，我聽著它睡著。"}, {"id": "grand_leave", "minAge": 1, "maxAge": 2, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 3, "cat": "家庭", "tone": "bad", "text": "爸媽要去外地工作了。他們出門那天，我在{elders}懷裡睡著，醒來的時候人已經不在了。我哭了好幾個晚上，後來就不哭了。", "group": "care", "fam": "隔代教養", "fx": {"lonely": 4}}, {"id": "grand_day_farm", "minAge": 0, "maxAge": 3, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["農"], "urban": null, "weight": 1.2, "cat": "家庭", "tone": "neutral", "text": "白天爸媽都下田，我給{elders}帶。{elders}輪流用揹巾把我綁在背上，煮飯、餵雞、去市場，我都在背上睡。", "group": "care"}, {"id": "grand_day", "minAge": 0, "maxAge": 3, "by": [1975, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["工", "小生意", "白領", "公教"], "urban": null, "weight": 0.8, "cat": "家庭", "tone": "neutral", "text": "爸媽白天都去上班，我給{elders}帶。{elders}家的電視整天開著，我在客廳的地板上爬來爬去。", "group": "care"}, {"id": "nanny", "minAge": 0, "maxAge": 3, "by": [1978, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["白領", "公教", "工"], "urban": true, "weight": 1, "cat": "家庭", "tone": "neutral", "text": "媽媽產假一結束就回去上班了。每天早上我被送到巷口的保母家，傍晚才被接回來。我一看到保母就伸手要抱，媽媽在旁邊站了一下。", "group": "care"}, {"id": "farm_daycare", "minAge": 2, "maxAge": 5, "by": [1961, 1975], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["農"], "urban": false, "weight": 1.2, "cat": "家庭", "tone": "neutral", "text": "農忙的時候，廟埕變成了托兒所。大人都下田了，一群小孩在廟口睡午覺，醒來就搶一顆饅頭。我搶到了，捨不得吃。", "group": "care"}, {"id": "living_factory", "minAge": 1, "maxAge": 5, "by": [1966, 1983], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["工", "農"], "urban": null, "weight": 1, "cat": "家庭", "tone": "neutral", "text": "客廳堆滿了要組裝的聖誕燈。媽媽一邊顧我，一邊把小燈泡一顆一顆插上去，一串算一點錢。我坐在旁邊幫忙排燈泡，排錯了也沒被罵。", "group": "care"}, {"id": "living_factory2", "minAge": 1, "maxAge": 5, "by": [1963, 1980], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["工", "農"], "urban": null, "weight": 0.8, "cat": "家庭", "tone": "neutral", "text": "媽媽在家做塑膠花的手工，桌上地上都是花瓣。我把花瓣撿起來黏在臉上，她笑了一下，又低頭繼續趕工。", "group": "care"}, {"id": "shop_candy", "minAge": 2, "maxAge": 6, "by": [1961, 1985], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["小生意"], "urban": null, "weight": 1.2, "cat": "家庭", "tone": "neutral", "text": "我在家裡的柑仔店長大。玻璃罐裡的糖果我都知道哪一罐最好吃，可是不能偷拿。客人一進門，我就大聲喊媽媽。", "group": "care"}, {"id": "shop_breakfast", "minAge": 2, "maxAge": 6, "by": [1980, 2005], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["小生意"], "urban": null, "weight": 1.2, "cat": "家庭", "tone": "neutral", "text": "家裡開早餐店。天還沒亮，爸媽就在煎蛋餅。我睡在店後面的折疊床上，常常被油煙嗆醒，翻個身又睡著。", "group": "care"}, {"id": "shop_nightmarket", "minAge": 2, "maxAge": 6, "by": [1975, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["小生意"], "urban": null, "weight": 1, "cat": "家庭", "tone": "neutral", "text": "家裡在夜市擺攤。我的晚餐常常是在攤子後面的小板凳上吃的。吃完就趴在紙箱上睡，醒來已經在回家的機車上。", "group": "care"}, {"id": "dorm", "minAge": 2, "maxAge": 6, "by": [1961, 1985], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": ["公教"], "urban": null, "weight": 1, "cat": "家庭", "tone": "neutral", "text": "我們住在學校的日式宿舍。榻榻米上可以打滾，院子裡有一棵很大的芒果樹。我每天都在樹下等芒果掉下來。"}, {"id": "epz", "minAge": 2, "maxAge": 6, "by": [1963, 1985], "y": null, "months": null, "region": null, "county": ["高雄市", "高雄縣", "台中縣"], "eth": null, "pjob": ["工"], "urban": null, "weight": 1.2, "cat": "家庭", "tone": "neutral", "text": "媽媽在加工出口區的工廠上班。每天傍晚，我坐在門口等那一群穿制服的阿姨騎腳踏車回來，一眼就能認出她。"}, {"id": "kinder_lang", "minAge": 4, "maxAge": 6, "by": [1961, 1990], "y": null, "months": null, "region": null, "county": null, "eth": ["閩南", "客家", "原住民"], "pjob": null, "urban": false, "weight": 1.2, "cat": "人生", "tone": "bad", "text": "我第一天上幼稚園。老師說的都是國語，我只聽得懂一半。我想上廁所，不知道怎麼說，就一直憋著。"}, {"id": "no_kinder", "minAge": 5, "maxAge": 6, "by": [1961, 1972], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": false, "weight": 1, "cat": "人生", "tone": "neutral", "text": "村子裡沒有幼稚園。我每天跟著哥哥姊姊在曬穀場跑來跑去，曬得跟木炭一樣黑。"}, {"id": "kinder_bib", "minAge": 4, "maxAge": 6, "by": [1970, 1995], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": true, "weight": 0.8, "cat": "人生", "tone": "neutral", "text": "我上了幼稚園，穿著小圍兜，帽子上繡著我的名字。第一天媽媽一走，我就抓著鐵門哭。"}, {"id": "kinder_english", "minAge": 4, "maxAge": 6, "by": [1995, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": true, "weight": 0.8, "cat": "人生", "tone": "neutral", "text": "我讀的是全美語幼稚園。回家我會說 apple、banana，可是{elders}聽不懂，只好拿真的香蕉給我。", "inc": ["中", "高"]}, {"id": "kinder_2012", "minAge": 4, "maxAge": 6, "by": [2006, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.6, "cat": "人生", "tone": "neutral", "text": "我上了幼兒園。第一天我沒有哭，倒是媽媽在門口站了很久才走。"}, {"id": "abacus", "minAge": 5, "maxAge": 6, "by": [1975, 1996], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": true, "weight": 0.8, "cat": "人生", "tone": "neutral", "text": "媽媽幫我報了珠心算。每天晚上我在桌上撥算盤，劈哩啪啦，算對了就可以看卡通。", "fx": {"study": 2}}, {"id": "piano", "minAge": 5, "maxAge": 6, "by": [1972, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": true, "weight": 0.8, "cat": "人生", "tone": "neutral", "text": "家裡多了一台直立鋼琴，我開始學琴。媽媽說很貴，要好好練。我每天坐在上面，腳還踩不到踏板。", "inc": ["高"]}, {"id": "born_girl", "minAge": 0, "maxAge": 0, "by": [1961, 1985], "y": null, "months": null, "region": null, "county": null, "eth": ["閩南", "客家", "外省"], "pjob": null, "urban": null, "weight": 0.8, "cat": "家庭", "tone": "bad", "text": "我出生的時候，{elders}在產房外面聽到是女孩，沒說什麼就先回家了。", "sex": "F"}, {"id": "fullmonth_boy", "minAge": 0, "maxAge": 0, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": ["閩南", "客家"], "pjob": null, "urban": null, "weight": 0.7, "cat": "家庭", "tone": "good", "text": "我滿月了。家裡煮了一大鍋油飯，裝成一盒一盒，送給左鄰右舍。", "sex": "M"}, {"id": "fullmonth_girl", "minAge": 0, "maxAge": 0, "by": [1975, 2010], "y": null, "months": null, "region": null, "county": null, "eth": ["閩南", "客家"], "pjob": null, "urban": null, "weight": 0.6, "cat": "家庭", "tone": "good", "text": "我滿月了。家裡訂了好幾盒蛋糕，分給左鄰右舍。", "sex": "F"}, {"id": "xinding", "minAge": 0, "maxAge": 1, "by": [1961, 2010], "y": null, "months": [2], "region": null, "county": ["桃園縣", "新竹縣", "新竹市", "苗栗縣"], "eth": ["客家"], "pjob": null, "urban": null, "weight": 1.5, "cat": "家庭", "tone": "good", "text": "我出生後的第一個元宵，家裡做了新丁粄，送到伯公廟和親戚家。廟裡貼出的名單上，有我的名字。", "sex": "M"}, {"id": "zhuazhou", "minAge": 1, "maxAge": 1, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": ["閩南", "客家", "外省"], "pjob": null, "urban": null, "weight": 0.6, "cat": "家庭", "tone": "good", "text": "我滿週歲那天，大人在我面前擺了算盤、毛筆、錢和印章，要我抓周。我爬過去，一把抓起了那支毛筆，放進嘴裡咬。大家都笑了。", "fx": {"study": 1}}, {"id": "zhuazhou2", "minAge": 1, "maxAge": 1, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": ["閩南", "客家", "外省"], "pjob": null, "urban": null, "weight": 0.4, "cat": "家庭", "tone": "good", "text": "我滿週歲那天抓周。我什麼都沒抓，只顧著拉大人的眼鏡，大家笑成一團。"}, {"id": "sibling", "minAge": 2, "maxAge": 5, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.7, "cat": "家庭", "tone": "neutral", "text": "我有了弟弟。媽媽在坐月子，房間裡都是麻油雞的味道。大人都圍著小嬰兒轉，我站在旁邊，突然覺得自己長大了。", "group": "sib"}, {"id": "sibling2", "minAge": 2, "maxAge": 5, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.7, "cat": "家庭", "tone": "neutral", "text": "我有了妹妹。她好小，哭聲好大。我偷偷摸了她的手，她就抓著我的手指不放。", "group": "sib"}, {"id": "flour_sack", "minAge": 2, "maxAge": 5, "by": [1961, 1966], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.2, "cat": "生活", "tone": "neutral", "text": "我穿的內褲是用麵粉袋改的。屁股上印著兩隻握在一起的手，還有「中美合作」四個字。", "inc": "低"}, {"id": "handmedown", "minAge": 2, "maxAge": 6, "by": [1961, 1995], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.7, "cat": "生活", "tone": "neutral", "text": "我身上的衣服都是表哥表姊穿過的，袖子要捲兩圈才看得到手。新衣服只有過年才有。", "inc": "低"}, {"id": "scooter", "minAge": 3, "maxAge": 6, "by": [1972, 2000], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.8, "cat": "生活", "tone": "good", "text": "爸爸騎機車載全家出門。我站在前面的踏板上，媽媽坐在後面。風很大，我瞇著眼睛，覺得自己好威風。"}, {"id": "move_city", "minAge": 1, "maxAge": 5, "by": [1961, 1985], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": true, "weight": 0.8, "cat": "家庭", "tone": "neutral", "text": "我們家從鄉下搬進城裡的公寓，四樓，沒有電梯。我第一次住在看不到田的地方，晚上一直說要回{elders}家。", "group": "move"}, {"id": "move_tower", "minAge": 2, "maxAge": 6, "by": [1985, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": true, "weight": 0.6, "cat": "家庭", "tone": "neutral", "text": "我們搬進了新的大樓，有管理員，有電梯。每次回家，我都要搶著按電梯，按錯樓層也不管。", "inc": ["中", "高"], "group": "move"}, {"id": "tv_bw", "minAge": 2, "maxAge": 6, "by": [1961, 2010], "y": [1964, 1965, 1966, 1967, 1968, 1969, 1970, 1971, 1972, 1973, 1974], "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1, "cat": "生活", "tone": "good", "text": "家裡買了第一台黑白電視。晚上鄰居都擠到我家客廳看，大人坐椅子，小孩坐地上。我坐在最前面，一直被叫說不要擋到。", "group": "tv"}, {"id": "puppet_tv", "minAge": 2, "maxAge": 6, "by": [1961, 2010], "y": [1970, 1971, 1972, 1973, 1974], "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.2, "cat": "生活", "tone": "neutral", "text": "中午一到，大人都放下手邊的事，圍著電視看布袋戲。我聽不懂在演什麼，可是史艷文一出場，我就跟著大人一起拍手。", "group": "tv"}, {"id": "cks_tv", "minAge": 1, "maxAge": 4, "by": [1961, 2010], "y": [1975], "months": [4, 5], "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.2, "cat": "生活", "tone": "neutral", "text": "電視節目突然都變成黑白的，卡通也不播了。大人講話都變得很小聲，我也跟著不敢吵。", "group": "tv"}, {"id": "tv_color", "minAge": 2, "maxAge": 6, "by": [1961, 2010], "y": [1977, 1978, 1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986], "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1, "cat": "生活", "tone": "good", "text": "家裡換了彩色電視。我第一次發現，卡通裡的天空原來是藍色的。", "group": "tv"}, {"id": "cartoon_530", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": [1978, 1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1992], "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.8, "cat": "生活", "tone": "neutral", "text": "每天傍晚五點半，我準時坐在電視前面等卡通。媽媽叫我吃飯，我說等一下，等廣告。", "group": "tv"}, {"id": "cable_kid", "minAge": 2, "maxAge": 5, "by": [1961, 2010], "y": [1993, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001], "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.8, "cat": "生活", "tone": "neutral", "text": "家裡裝了第四台。我發現有一台整天都在播卡通，從此我早上都比爸媽還早起。", "group": "tv"}, {"id": "tablet", "minAge": 1, "maxAge": 5, "by": [1961, 2010], "y": [2011, 2012, 2013, 2014, 2015, 2016], "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1, "cat": "生活", "tone": "neutral", "text": "我還不太會說話，就會用手指滑平板了。吃飯的時候，大人把手機架在我面前，我才肯張嘴。", "group": "tv"}, {"id": "pudu", "minAge": 3, "maxAge": 6, "by": [1965, 2010], "y": null, "months": [8], "region": null, "county": null, "eth": ["閩南", "客家"], "pjob": null, "urban": null, "weight": 0.7, "cat": "生活", "tone": "neutral", "text": "中元普渡，家門口擺了一整桌供品。大人說拜完才能吃，我一直盯著那包乖乖，等香燒完。"}, {"id": "mazu", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [3, 4], "region": "中", "county": null, "eth": ["閩南", "客家"], "pjob": null, "urban": null, "weight": 1, "cat": "生活", "tone": "neutral", "text": "媽祖遶境經過家門口，鞭炮聲好大。我摀著耳朵，{elders}卻拉著我去鑽轎底。鑽過去以後，我覺得自己好像變勇敢了。"}, {"id": "temple_opera", "minAge": 3, "maxAge": 6, "by": [1961, 1990], "y": null, "months": null, "region": null, "county": null, "eth": ["閩南"], "pjob": null, "urban": null, "weight": 0.7, "cat": "生活", "tone": "neutral", "text": "廟口在演歌仔戲。我坐在{elders}旁邊的板凳上，戲還沒演完就睡著了，嘴裡還含著一顆糖。"}, {"id": "harvest", "minAge": 3, "maxAge": 6, "by": [1961, 1990], "y": null, "months": [6, 7, 10, 11], "region": null, "county": null, "eth": null, "pjob": ["農"], "urban": null, "weight": 1, "cat": "生活", "tone": "good", "text": "割稻的時候全家都在田裡。我在田埂上抓青蛙，抓到就放進奶粉罐裡。晚上{elders}煮了一大鍋點心，給來幫忙的人吃。"}, {"id": "stitches", "minAge": 2, "maxAge": 6, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1, "cat": "健康", "tone": "bad", "text": "我在家裡跑太快，額頭撞到桌角，血流了滿臉。去診所縫了三針，我哭到沒聲音。從此我額頭多了一道小小的疤。", "group": "accident", "flag": "scar"}, {"id": "lost_market", "minAge": 3, "maxAge": 6, "by": [1961, 2000], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.8, "cat": "生活", "tone": "bad", "text": "我在夜市跟大人走散了。我站在原地一直哭，賣香腸的阿伯把我抱到攤子上，給我一根香腸，一直等到媽媽跑回來。", "group": "accident"}, {"id": "lost_mall", "minAge": 3, "maxAge": 6, "by": [1990, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": true, "weight": 0.8, "cat": "生活", "tone": "bad", "text": "我在大賣場跟大人走散了。廣播裡唸出我的名字，我一聽，眼淚就掉下來。", "group": "accident"}, {"id": "dog_chase", "minAge": 3, "maxAge": 6, "by": [1961, 1990], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": false, "weight": 0.8, "cat": "生活", "tone": "bad", "text": "我被巷口的狗追，跑到一半跌倒，膝蓋全破了。{elders}幫我擦紅藥水，痛得我哇哇叫，我發誓再也不走那條巷子。", "group": "accident"}, {"id": "exhaust_burn", "minAge": 3, "maxAge": 6, "by": [1970, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.8, "cat": "健康", "tone": "bad", "text": "我的小腿碰到機車排氣管，燙出一個大水泡。後來那裡留下一塊淡淡的疤，夏天穿短褲就看得到。", "group": "accident", "flag": "scar"}, {"id": "thermos_burn", "minAge": 1, "maxAge": 4, "by": [1961, 1995], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.7, "cat": "健康", "tone": "bad", "text": "我打翻了熱水瓶，手背燙紅了一大片。{elders}抓了一把牙膏就往上塗，我痛得一直甩手。", "group": "accident"}, {"id": "coin", "minAge": 1, "maxAge": 3, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.5, "cat": "健康", "tone": "neutral", "text": "我把一塊錢硬幣吞下去了。全家大人緊張了兩天，每天都在檢查我的大便。", "group": "accident"}, {"id": "iron_door", "minAge": 3, "maxAge": 6, "by": [1975, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 0.5, "cat": "健康", "tone": "bad", "text": "我的手指被鐵捲門夾到，指甲整片黑掉。過了好久才長出新的，我每天都去看它長了沒。", "group": "accident"}, {"id": "fest_amis", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [7, 8], "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": false, "weight": 2, "cat": "生活", "tone": "good", "text": "部落的豐年祭到了。我在大圈圈外面跟著學跳舞，跳錯了也沒人罵我。晚上{elders}喝了酒，用族語唱了好久的歌。", "tribe": ["阿美"], "group": "fest"}, {"id": "fest_puyuma", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [12], "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": false, "weight": 2, "cat": "生活", "tone": "good", "text": "年祭到了。哥哥們去山上打獵，三天後背著獵物回來，整個部落都在門口迎接。我跟著大人喊，喊得好大聲。", "tribe": ["卑南"], "group": "fest"}, {"id": "fest_paiwan", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [7, 8], "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": false, "weight": 2, "cat": "生活", "tone": "good", "text": "小米收穫了。部落的廣場上，大人圍成一圈跳舞，頭上戴著花環。{elders}幫我戴了一個，花太大，一直遮住眼睛。", "tribe": ["排灣", "魯凱"], "group": "fest"}, {"id": "fest_tao", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [2, 3], "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": false, "weight": 2, "cat": "生活", "tone": "good", "text": "飛魚季開始了。大人把拼板舟推下海，我站在岸邊的石頭上，看著船越划越遠，一直到看不見。", "tribe": ["達悟"], "group": "fest"}, {"id": "fest_bunun", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [4, 5], "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": false, "weight": 2, "cat": "生活", "tone": "good", "text": "射耳祭那天，爸爸握著我的手拉弓。箭沒射出去多遠，大人還是拍手叫好。", "tribe": ["布農"], "group": "fest"}, {"id": "fest_atayal", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [7, 8], "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": false, "weight": 2, "cat": "生活", "tone": "good", "text": "祖靈祭的清早，天還沒亮，大人就帶著吃的上山。我被{elders}牽著走在最後面，大人說不能回頭看。", "tribe": ["泰雅", "太魯閣", "賽德克"], "group": "fest"}, {"id": "fest_saisiyat", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [11], "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": false, "weight": 2, "cat": "生活", "tone": "good", "text": "矮靈祭的歌唱了一整夜。我靠在媽媽身上，聽到睡著，又被歌聲叫醒。", "tribe": ["賽夏"], "group": "fest"}, {"id": "fest_tsou", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [2], "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": false, "weight": 2, "cat": "生活", "tone": "good", "text": "戰祭那天，男人們聚在會所前面。我是小孩，只能在外面看，看著爸爸穿上紅色的衣服，好像變了一個人。", "tribe": ["鄒"], "group": "fest"}, {"id": "tribe_song", "minAge": 0, "maxAge": 3, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": null, "weight": 1, "cat": "家庭", "tone": "good", "text": "{elders}只跟我說族語。我學會的第一首歌，是{elders}哄我睡覺時唱的，我還不知道那是什麼意思。"}, {"id": "urban_tribe", "minAge": 1, "maxAge": 6, "by": [1965, 1995], "y": null, "months": null, "region": null, "county": null, "eth": "原住民", "pjob": null, "urban": true, "weight": 1.5, "cat": "家庭", "tone": "neutral", "text": "爸爸在工地做模板，我們住在河邊的鐵皮屋。附近住的都是從部落下來的人，晚上大家一起烤肉唱歌，我就在旁邊玩到睡著。"}, {"id": "hakka_guazhi", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [2, 3], "region": null, "county": null, "eth": "客家", "pjob": null, "urban": null, "weight": 1.2, "cat": "家庭", "tone": "neutral", "text": "元宵過後，全家上山掛紙。我跟著大人在墳上壓紙錢，{elders}要我跟阿太講話，我不知道要說什麼，就鞠了三個躬。"}, {"id": "hakka_yimin", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [8, 9], "region": null, "county": ["新竹縣", "新竹市", "桃園縣"], "eth": "客家", "pjob": null, "urban": null, "weight": 1.2, "cat": "生活", "tone": "neutral", "text": "義民節到了，廟前擺滿了神豬。我站在最大的那隻前面，嘴巴張得好大，忘了害怕。"}, {"id": "juancun_alley", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 2, "cat": "生活", "tone": "good", "text": "眷村的巷子很窄，家家戶戶門對門。山東伯伯的饅頭剛蒸好，隔壁四川媽媽在曬辣椒。我端著碗，從巷頭吃到巷尾。", "juancun": true}, {"id": "juancun_ration", "minAge": 2, "maxAge": 5, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": null, "pjob": null, "urban": null, "weight": 1.5, "cat": "家庭", "tone": "neutral", "text": "每個月領眷糧的日子，爸爸扛回一大袋米和一桶油。我跟在後面，搶著幫忙拿那包鹽。", "juancun": true}, {"id": "waisheng_radio", "minAge": 3, "maxAge": 6, "by": [1961, 1990], "y": null, "months": null, "region": null, "county": null, "eth": "外省", "pjob": null, "urban": null, "weight": 1, "cat": "家庭", "tone": "neutral", "text": "{elders}每天都聽收音機裡的京戲，一邊聽一邊打拍子。我坐在爺爺腿上，聽不懂，可是很喜歡他身上的萬金油味道。"}, {"id": "typhoon_coast", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [7, 8, 9], "region": null, "county": ["澎湖縣", "宜蘭縣", "基隆市", "屏東縣", "台東縣", "花蓮縣", "雲林縣", "嘉義縣", "台南縣", "高雄縣", "金門縣", "新竹縣", "苗栗縣", "連江縣"], "eth": null, "pjob": null, "urban": false, "weight": 1.2, "cat": "生活", "tone": "bad", "text": "颱風要來了。爸爸跟叔叔們去港口把船綁緊，回來的時候全身濕透。那天晚上停電，我們點著蠟燭，聽外面的風一直叫，我躲在棉被裡不敢出來。"}, {"id": "kinmen_shell", "minAge": 2, "maxAge": 6, "by": [1961, 2010], "y": [1961, 1962, 1963, 1964, 1965, 1966, 1967, 1968, 1969, 1970, 1971, 1972, 1973, 1974, 1975, 1976, 1977, 1978], "months": null, "region": null, "county": ["金門縣", "連江縣"], "eth": null, "pjob": null, "urban": null, "weight": 3, "cat": "生活", "tone": "bad", "text": "單號的晚上，砲聲一響，媽媽就抱著我躲進防空洞。我在裡面睡著了，醒來時天已經亮了。"}, {"id": "kinmen_dark", "minAge": 2, "maxAge": 6, "by": [1961, 2010], "y": [1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1992], "months": null, "region": null, "county": ["金門縣", "連江縣"], "eth": null, "pjob": null, "urban": null, "weight": 3, "cat": "生活", "tone": "neutral", "text": "晚上家裡的窗戶要用黑布遮起來，一點光都不能漏出去。我在黑黑的屋裡，聽大人小聲講話，也學著小聲。"}, {"id": "penghu_wind", "minAge": 3, "maxAge": 6, "by": [1961, 2010], "y": null, "months": [11, 12, 1, 2], "region": null, "county": ["澎湖縣"], "eth": null, "pjob": null, "urban": null, "weight": 3, "cat": "生活", "tone": "neutral", "text": "冬天的風大到我走不動。{elders}牽著我，經過咾咕石砌的菜宅，牆後面種著高麗菜。我把臉埋進大人的外套裡。"}, {"id": "newimm_lullaby", "minAge": 0, "maxAge": 2, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": "新住民子女", "pjob": null, "urban": null, "weight": 2, "cat": "家庭", "tone": "neutral", "text": "媽媽哄我睡覺時，唱的是她家鄉的歌。{elders}在旁邊聽到，叫她要跟我講國語。她就不唱了，改成輕輕拍我的背。", "momFrom": ["越南", "印尼", "泰國", "菲律賓"]}, {"id": "newimm_visit", "minAge": 2, "maxAge": 5, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": "新住民子女", "pjob": null, "urban": null, "weight": 1.5, "cat": "家庭", "tone": "good", "text": "媽媽帶我回外婆家。外婆抱著我一直哭，說的話我一句都聽不懂。那裡好熱，我在吊床上睡了一整個下午。", "momFrom": ["越南", "印尼", "泰國", "菲律賓"]}, {"id": "newimm_class", "minAge": 1, "maxAge": 4, "by": [1961, 2010], "y": [2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014], "months": null, "region": null, "county": null, "eth": "新住民子女", "pjob": null, "urban": null, "weight": 1.5, "cat": "家庭", "tone": "neutral", "text": "媽媽每個禮拜去上識字班，把我背在背上。我在教室後面睡覺，她在前面一個字一個字念注音。"}, {"id": "newimm_market", "minAge": 2, "maxAge": 5, "by": [1961, 2010], "y": null, "months": null, "region": null, "county": null, "eth": "新住民子女", "pjob": null, "urban": null, "weight": 1.2, "cat": "家庭", "tone": "neutral", "text": "媽媽牽著我去菜市場。賣菜的阿姨聽到她的口音，問她是哪裡來的。媽媽笑著回答，把我的手握得更緊。"}, {"id": "quake_921_baby", "minAge": 0, "maxAge": 2, "by": [1961, 2010], "y": [1999], "months": [9], "region": null, "county": ["台中縣", "台中市", "南投縣", "彰化縣", "雲林縣", "苗栗縣"], "eth": null, "pjob": null, "urban": null, "weight": 4, "cat": "生活", "tone": "bad", "text": "半夜一陣天搖地動，媽媽抱著我衝到外面。後來好幾個禮拜，我們一家都睡在路邊的帳篷裡。我每晚都要抱著媽媽才肯睡。"}, {"id": "morakot_kid", "minAge": 0, "maxAge": 4, "by": [1961, 2010], "y": [2009], "months": [8], "region": null, "county": ["高雄縣", "屏東縣", "台東縣", "台南縣", "嘉義縣"], "eth": null, "pjob": null, "urban": null, "weight": 4, "cat": "生活", "tone": "bad", "text": "大雨下了好幾天。水淹進一樓，爸爸把我抱到冰箱上面坐好，自己在下面舀水。我抱著布娃娃，一動也不敢動。"}];const RM={"blind": [{"y": [1961, 1988], "text": "媒人帶我去相親。兩家人坐在冰果室裡，大人一直在講話，{n}從頭到尾只抬頭看了我兩次。回家的路上，我一直想那兩次是什麼意思。", "ch": "matchmaker"}, {"y": [1961, 1988], "text": "我被拉去相親。{n}的媽媽問我會不會煮飯、做什麼工作、家裡有幾個兄弟。我答完，{n}偷偷對我笑了一下。", "ch": "family"}, {"y": [1961, 1985], "sex": "M", "text": "相親那天我穿了借來的西裝，袖子太長。{n}一直盯著我的袖口，我緊張到茶杯都拿不穩。", "ch": "matchmaker"}, {"y": [1975, 1995], "text": "相親約在西餐廳，我第一次拿刀叉，切牛排切到盤子吱吱叫。{n}假裝沒聽到，我很感激。", "ch": "family"}, {"y": [1980, 2010], "text": "長輩說{n}條件不錯，叫我去見一面。我本來只想交差，結果我們聊了兩個鐘頭，最後是餐廳要打烊才走。", "ch": "family"}, {"y": [2000, 2030], "text": "過年回家，阿姨又幫我安排了相親。我已經不太抱希望，沒想到{n}也是被硬拉來的，我們在桌子底下互傳簡訊吐槽。", "ch": "family"}], "meet": [{"y": [1961, 1990], "text": "{n}是工廠隔壁線的。午休時間，我每天都故意去{p}那一桌的旁邊吃便當。", "myJob": ["工廠"], "ptJob": "same", "need": ["working"], "ch": "workFactory"}, {"y": [1965, 2030], "text": "我在教會的團契認識了{n}。{p}彈吉他唱詩歌，我在台下一直看錯拍子。", "ch": "faith"}, {"y": [1965, 1992], "text": "我交了一個筆友，就是{n}。我們寫了半年的信才第一次見面，{p}本人比照片裡害羞。", "ch": "letters"}, {"y": [1970, 1995], "maxAge": 26, "text": "救國團的營隊上，我跟{n}被分到同一小隊。營火晚會跳土風舞時，輪到我們牽手，我手心全是汗。", "ch": "mixer"}, {"y": [1975, 2005], "maxAge": 26, "text": "大學聯誼那天抽鑰匙，我抽到{n}的機車。{p}載我騎了一整個下午，我一路上都不知道手要放哪裡。", "need": ["student"], "ptJob": "student", "ch": "mixer"}, {"y": [1996, 2005], "text": "我在聊天室認識了{n}。我們每天晚上聊到撥接被媽媽切斷，隔天再繼續。", "ch": "bbs"}, {"y": [2001, 2011], "text": "我在 MSN 上跟{n}越聊越晚。{p}的暱稱每天都換，我每天都會先去看{p}換成什麼。", "ch": "msn"}, {"y": [2009, 2018], "text": "{n}在臉書上按了我好幾篇讚，後來我們開始私訊。第一次見面時，我們都說本人比照片好看。", "ch": "fb"}, {"y": [2013, 2040], "text": "我在交友軟體上滑到{n}。我們配對以後聊了兩個禮拜，約在捷運站出口見面，我提早到了二十分鐘。", "ch": "app"}, {"y": [1990, 2040], "text": "{n}是朋友婚禮上同一桌的。新人敬酒的時候，我們發現彼此都在偷偷看手錶，就笑了出來。", "ch": "wedding"}, {"y": [1985, 2040], "text": "{n}是公司新來的同事。第一次一起加班到半夜，{p}分了我一半的便當。", "myJob": ["公司", "科技", "服務", "醫護"], "ptJob": "same", "need": ["working"], "ch": "workOffice"}], "together": [{"y": [1975, 1998], "text": "我在{n}家樓下的公共電話亭，投了三次硬幣才敢開口說喜歡{p}。電話那頭安靜了很久，然後{p}說好。"}, {"y": [1961, 1990], "text": "我寫了一封很長的信給{n}，寄出去以後每天都去看信箱。第五天，回信來了，只有一行字，我讀了一整晚。"}, {"y": [1993, 2001], "text": "我在 BB Call 上打了 520，按完就後悔。過了十分鐘，{n}回了 530。"}, {"y": [2001, 2011], "text": "我在 MSN 上打了好幾次「我們要不要在一起」，又刪掉。最後是{n}先問的。"}, {"y": [2011, 2040], "text": "我傳 LINE 問{n}要不要在一起，訊息顯示已讀，三分鐘沒回。那三分鐘，我把手機翻過來又翻回去。"}, {"y": [1961, 2040], "text": "看完電影走出來，{n}突然牽了我的手。我們都沒說話，就這樣走到公車站。"}, {"y": [1975, 2005], "minAge": 16, "maxAge": 18, "text": "高中的時候，我們偷偷在一起，怕被教官看到，放學都在離學校兩站的地方才會合。"}], "date": [{"y": [1961, 1985], "text": "我們去看電影。戲院裡很多人在抽菸，我什麼都沒看進去，只記得{n}的肩膀碰到我的那一下。"}, {"y": [1965, 1990], "text": "我騎腳踏車載{n}去河堤。我們坐在草地上吃一包五香乖乖，誰也不敢先說要回家。"}, {"y": [1975, 1998], "text": "每天晚上，我在巷口的公共電話跟{n}講到零錢用完。"}, {"y": [1965, 1998], "text": "打電話去{n}家，常常是{p}爸爸接的。我每次都先清一下喉嚨，再很有禮貌地說要找{n}。"}, {"y": [1978, 1998], "text": "我們去吃西餐，一客牛排送玉米濃湯和紅茶。我存了兩個禮拜的錢，結帳時故意裝得很自然。"}, {"y": [1985, 1998], "text": "我們去了 MTV 包廂看電影，片子演了什麼，我後來一點都想不起來。"}, {"y": [1980, 2000], "text": "我們去溜冰場，{n}一直摔，我一直扶。後來才知道，{p}其實會溜。"}, {"y": [1985, 2040], "text": "我們騎機車環島，晚上住在墾丁的民宿，聽海聽到睡著。"}, {"y": [1993, 2015], "text": "我們在 KTV 唱到天亮，出來的時候早餐店剛開門。{n}靠在我肩上睡著了。"}, {"y": [1993, 2010], "text": "我們去漫畫店待了一整個下午，各看各的，偶爾抬頭對看一眼。"}, {"y": [1990, 2040], "text": "我們在夜市一攤一攤吃過去，最後一起分一杯珍奶。"}, {"y": [2010, 2040], "text": "週末我們去咖啡廳，{n}拍了二十張照片才開始喝。我的那杯已經冷了。"}, {"y": [2012, 2040], "text": "我們一起追完了一整季的劇，{n}看到最後一集哭得比我還慘。"}, {"y": [2012, 2040], "text": "我們一起去收容所領養了一隻貓。{n}說這樣我們就算是一個家了，我笑{p}太誇張，心裡卻很高興。"}, {"y": [1961, 2040], "text": "{n}住得遠，每個週末我都坐好幾個小時的車去找{p}。車票我都留著，夾在筆記本裡。"}], "habit": [{"delta": -1, "axis": "risk", "text": "{n}約會總是遲到。我等了二十分鐘，{p}一出現就笑，我的氣也只剩一半。"}, {"delta": -1, "axis": "open", "text": "{n}擠牙膏都從中間擠，我習慣從尾巴。我們為了這件事，認真地討論了一個晚上。"}, {"delta": -3, "axis": "risk", "text": "{n}花錢很大方，看到喜歡的就買。我看著發票，算了一下我們這個月還剩多少。"}, {"delta": -3, "axis": "self", "text": "{n}什麼事都要問過爸媽。每次要做決定，我都覺得我們中間還坐著兩個人。"}, {"delta": -1, "axis": "risk", "text": "{n}每個週末都想出去玩，我只想在家睡覺。我們輪流，一個週末出門，一個週末在家。"}, {"delta": -2, "axis": "self", "y": [1990, 2040], "text": "{n}一打起電動就聽不到我說話。我在旁邊講了半天，{p}只回了一聲「嗯」。"}, {"delta": -2, "axis": "self", "y": [2005, 2040], "text": "{n}回訊息很慢，我常常盯著手機等。後來我才知道，{p}只是不習慣一直拿著手機。"}, {"delta": 1, "axis": "open", "y": [2005, 2040], "text": "約會吃飯，{n}堅持要各付各的。我一開始覺得怪怪的，後來覺得這樣比較輕鬆。"}, {"delta": -1, "axis": "open", "y": [1961, 2005], "sex": "M", "text": "每次吃飯都是我付錢。{n}說這是應該的，我嘴上說好，月底看著存摺有點心虛。"}, {"delta": 1, "text": "{n}吃什麼都要加辣，我一點都不能吃。後來我們點菜都點兩份，一份加辣，一份不加。"}, {"delta": -2, "axis": "self", "y": [1995, 2040], "text": "我們開始住在一起，我才知道{n}的襪子會丟在沙發上，碗會泡到隔天。{p}也才知道，我睡覺會磨牙。"}, {"delta": -2, "axis": "open", "text": "{n}的朋友很多，每個週末都有聚會。我坐在一群不認識的人中間，笑到臉都僵了。"}, {"delta": 1, "text": "{n}很愛乾淨，我進門沒脫鞋就被唸。後來我養成習慣，連回自己家都會先脫鞋。"}, {"delta": -3, "axis": "rebel", "text": "{n}吵架的時候會冷戰，我習慣當下就講開。第一次冷戰，我整整三天睡不好。"}, {"delta": 2, "axis": "risk", "text": "我們開始一起存錢。{n}拿了一本存摺給我看，上面的數字比我想的多。我有點不好意思拿出我的。"}, {"delta": 3, "text": "{n}很會照顧人，我感冒的時候{p}煮了一鍋粥，鹽放太多，我還是吃完了。"}], "fight": [{"text": "我們為了誰比較忙大吵了一架。{n}說我心裡只有工作，我說還不是為了我們。說完我們都安靜了。"}, {"y": [2005, 2040], "text": "{n}看到我手機裡前任的照片，整晚都不跟我說話。我解釋了很久，越解釋越像藉口。"}, {"text": "{n}的同事送{p}回家，我在樓下看到了。那天晚上我們吵到鄰居來敲門。"}, {"text": "我們為了錢吵架。{n}覺得我太省，我覺得{p}太敢花。吵到最後，其實都是在吵以後。"}, {"text": "我忘了{n}的生日。{p}一整天都在等，等到半夜才傳了一句「沒關係」。我知道那不是沒關係。"}, {"y": [1980, 2040], "text": "{n}說想去國外念書，問我要不要一起。我說我走不開，{p}說那我們怎麼辦。"}, {"text": "我們吵架的時候，我說了一句很難聽的話。話一出口我就後悔了，可是收不回來。"}, {"text": "{n}說每次都是{p}在遷就我。我想反駁，卻想不出一件我遷就過{p}的事。"}, {"y": [2000, 2040], "text": "我們吵的是要不要買房子。{n}想先買，我想先存。吵到最後，我們都說不出到底在怕什麼。"}, {"text": "過年要回誰家，我們吵了一個禮拜。最後決定除夕回一家，初二回另一家，誰都不太滿意。"}], "makeup": [{"text": "後來是我先打電話過去的。電話一接通，我們都說了對不起，然後一起笑了。"}, {"text": "{n}隔天在我家門口等我，手上拿著一袋我最愛吃的雞蛋糕。我們什麼都沒說，就坐在樓梯上吃完。"}, {"y": [2011, 2040], "text": "冷戰了三天，我傳了一張貓咪道歉的貼圖。{n}回了一個翻白眼，我就知道沒事了。"}, {"y": [1980, 2040], "text": "我寫了一張卡片，塞進{n}的機車置物箱。{p}看完，打電話來叫我出去吃宵夜。"}, {"text": "我們都不是會先道歉的人。後來是{n}的媽媽打電話來，問我禮拜天要不要回去吃飯，我們就和好了。"}, {"text": "我們坐下來好好談了一次，把彼此不喜歡的地方都講出來。講完以後，我覺得我們比以前更像一對。"}, {"text": "我在{n}家樓下站了兩個鐘頭。{p}終於下來的時候，眼睛是腫的，我的也是。"}], "family": [{"cond": "ok", "delta": -2, "y": [1961, 1990], "text": "第一次去{n}家，我提了一盒蘋果。{p}爸爸一句話都沒說，只問我在哪裡上班。"}, {"cond": "ok", "delta": 4, "text": "第一次去{n}家，我在門口深呼吸了三次。{p}媽媽一直夾菜給我，碗裡的菜堆得像一座山。"}, {"cond": "ok", "delta": 2, "y": [2005, 2040], "text": "見家長前，{n}先傳了一張全家福給我，教我每個人要怎麼叫。我背了一路，進門還是叫錯了一個。"}, {"cond": "ok", "delta": 5, "text": "{n}第一次來我家。我爸一直問{p}會不會喝酒，{p}硬是陪我爸喝到半夜。隔天我爸說：「這個可以。」"}, {"cond": "mixed_wai", "delta": -15, "me": "外省", "text": "{n}爸爸知道我是外省人以後，就不肯再跟我說話。吃飯的時候，他一直用台語跟{n}講話，我一句也聽不懂。"}, {"cond": "mixed_wai", "delta": -12, "me": "外省", "text": "我爸知道{n}是本省人，臉色就變了。他說：「我們家的事，他們不會懂的。」我聽了很難過，可是不知道怎麼回。"}, {"cond": "mixed_wai", "delta": 2, "me": "本省", "text": "{n}的爺爺從大陸來，在飯桌上講起家鄉，講到一半就停了。我不知道該說什麼，只好幫他添了一碗飯。"}, {"cond": "mixed_wai", "delta": -12, "me": "本省", "text": "我阿公聽到{n}是外省人，飯也不吃了，回房間把門關上。我在門外站了很久，不知道要說什麼。"}, {"cond": "poor", "delta": -10, "text": "{n}媽媽問我爸媽是做什麼的。我說了，她笑了一下，就把話題轉開了。"}, {"cond": "poor", "delta": -8, "y": [1961, 2000], "text": "{n}家問我們的聘金要多少。我爸媽在房間裡算了一整晚，第二天我看到我媽的眼睛紅紅的。"}, {"cond": "rich", "delta": -6, "text": "{n}家住在有電梯的大樓，客廳比我家整間還大。我坐在沙發上，不敢靠到椅背。"}, {"cond": "lang", "delta": -2, "text": "{n}家講的話，我只聽得懂一半。{p}阿嬤一直對我笑，我也一直笑，不知道我們到底聊了什麼。"}, {"cond": "lang", "delta": 3, "ptEth": "客家", "text": "{n}的阿婆用客家話問我會不會做粄。我搖頭，她說沒關係，以後她教我。"}, {"cond": "ind", "delta": -10, "me": "原住民", "text": "{n}媽媽問我是哪一族，然後就沒有再問了。那頓飯吃得很安靜。"}, {"cond": "ind", "delta": 6, "me": "原住民", "text": "我帶{n}回部落。{p}被我舅舅們灌酒灌到臉紅，隔天早上還是很早起來幫忙殺雞。我舅舅拍著{p}的肩膀笑。"}, {"cond": "newimm", "delta": -8, "text": "{n}媽媽知道我媽媽是從國外嫁來的，問了好幾次我媽媽「以前在那邊是做什麼的」。我每次都回答，回答到最後，有點累了。"}, {"cond": "house", "delta": -10, "y": [2005, 2040], "text": "{n}媽媽問我們結婚以後要住哪裡。我說先租房子，她沉默了很久，最後說：「沒有房子，怎麼給人家一個家？」"}, {"cond": "bazi", "delta": -10, "text": "{n}家拿我們的八字去算，算命的說我們相沖。{p}媽媽從此看我的眼神都不太一樣。"}, {"cond": "eldest", "delta": -6, "sex": "F", "text": "{n}是長子，{p}媽媽說結婚以後要住在家裡，一起照顧爸媽。我點了頭，回家以後一整晚沒睡。"}, {"cond": "faith", "delta": -5, "text": "{n}家是基督徒，{p}媽媽問我家有沒有在拿香。我說有，她說沒關係，可是那頓飯她禱告得特別久。"}, {"cond": "divorced", "delta": -8, "text": "{n}家知道我離過婚。{p}爸爸沒說什麼，只是那天晚上，我聽到他們在房間裡講了很久。"}], "ready": [{"text": "我們開始會聊以後要住在哪裡。"}, {"y": [1990, 2040], "text": "{n}拿了一張預售屋的廣告給我看，說這間的格局不錯。我看了價錢，又看了{p}一眼，我們都沒說話。"}, {"text": "我們開始一起存結婚基金，存摺放在{n}那裡。每個月存進去的那天，我們會去吃一碗牛肉麵慶祝。"}, {"text": "我爸媽開始叫{n}回家吃飯了。過年的時候，{p}也拿到了我家的紅包。"}, {"text": "我們去看了喜餅。試吃了五家，{n}都說好吃，最後是我做的決定。"}, {"y": [1990, 2040], "text": "我在{n}最喜歡的餐廳求婚。戒指盒打開的那一刻，隔壁桌的人先鼓掌了。", "commit": true}, {"y": [2005, 2040], "text": "我們決定先去登記，婚禮以後再說。從戶政事務所出來，我們去吃了一碗豆花。", "commit": true}, {"y": [1961, 2005], "text": "兩家人約在餐廳提親。大人談聘金、談日子，我跟{n}在桌子底下偷偷牽手。", "commit": true}, {"y": [1985, 2040], "text": "{n}發現懷孕了。我們在診所外面站了很久，然後我說：「那我們結婚吧。」", "sex": "M", "commit": true}, {"y": [1985, 2040], "sex": "F", "text": "我發現自己懷孕了。我們在診所外面站了很久，然後{n}說：「那我們結婚吧。」", "commit": true}], "breakup": [{"why": "fam", "text": "{n}家裡一直反對。最後是{p}先說的：「我們不要再讓大家為難了。」我說好，掛了電話以後，我蹲在地上很久。"}, {"why": "wait", "text": "我們在一起太久了，久到不知道下一步是什麼。有一天，{n}說{p}累了，我竟然鬆了一口氣。"}, {"why": "wait", "text": "{n}一直在等我開口談結婚，我一直說再等等。等到最後，{p}不等了。"}, {"why": "far", "text": "{n}調到外地工作，我們一個月只見一次面。後來電話越打越短，最後就不打了。"}, {"why": "far", "y": [1961, 2000], "text": "{n}出國念書，我們約好每個禮拜寫信。第一年寫得很勤，第二年，信越來越少。"}, {"why": "far", "y": [2005, 2040], "text": "我們隔著時差視訊，一個剛起床，一個準備睡。後來我們都說，這樣好累。"}, {"why": "plain", "text": "沒有誰做錯什麼，我們只是越來越沒話說。分手那天，我們還一起吃完了那頓飯。"}, {"why": "plain", "y": [1975, 1998], "text": "我們分手了。我把{n}送的卡帶收進紙箱，放在衣櫃最上面。"}, {"why": "plain", "y": [2001, 2011], "text": "我們分手了。我刪掉了 MSN 上{n}的名字，又加回來，又刪掉。"}, {"why": "plain", "y": [2014, 2040], "text": "我們分手了。我封鎖了{n}的 IG，過了三天，又忍不住用分身帳號去看。"}, {"why": "army", "sex": "M", "y": [1961, 2040], "text": "我在當兵。放假回家，{n}約我出來，說{p}喜歡上別人了。收假那天，我在火車上一句話都沒說。"}, {"why": "army", "sex": "M", "y": [1961, 2005], "text": "我在營區排了好久的隊打公共電話，{n}的電話一直沒人接。後來我收到一封信，我在站哨的時候讀完它。"}, {"why": "cheat", "text": "我發現{n}跟別人在一起。{p}說對不起，說了很多次。我把{p}留在我家的東西裝成一袋，放在門口。"}, {"why": "future", "y": [1990, 2040], "text": "{n}想要小孩，我還沒準備好。我們談了很多次，每次都談到一樣的地方停下來。"}, {"why": "future", "y": [1990, 2040], "text": "{n}決定去國外工作，問我要不要一起去。我想了一個禮拜，還是說不要。"}], "remarry": [{"minAge": 40, "maxAge": 75, "y": [1996, 2040], "text": "同學會上，我又遇到了{n}。我們都一個人了，散場以後一起走到捷運站，走得很慢。"}, {"minAge": 40, "maxAge": 75, "y": [1998, 2040], "text": "我在社區大學的書法班認識了{n}。下課以後，我們常常一起去喝一杯豆漿。"}, {"minAge": 50, "maxAge": 80, "text": "公園裡跳土風舞的人裡，{n}每次都站在我旁邊。跳了半年，{p}才問我要不要去吃早餐。"}, {"minAge": 40, "maxAge": 80, "need": "kids", "text": "我的孩子知道我在跟{n}交往，好幾天沒跟我說話。後來有一天，孩子問我：「那{p}對你好嗎？」"}, {"minAge": 45, "maxAge": 80, "y": [2000, 2040], "text": "我跟{n}都不想再結一次婚了。我們各自住各自的家，週末一起去爬山。這樣剛剛好。"}], "flirt": [{"y": [1961, 1985], "text": "{n}下班會繞路經過我家門口。我躲在窗戶後面，數{p}這個禮拜經過了幾次。"}, {"y": [1961, 1990], "text": "我約{n}去看電影，還多找了兩個朋友壯膽。朋友很識相，散場就說要先走了。"}, {"y": [1965, 1995], "text": "{n}寄了一張卡片給我，上面只寫了天氣跟最近在忙什麼。我看了好幾遍，想找出別的意思。"}, {"y": [1975, 1998], "text": "我在{n}家巷口的公共電話前站了很久，硬幣握到發燙，最後還是沒有打。"}, {"y": [1998, 2012], "text": "我們在 MSN 上聊到半夜。{n}的暱稱改成一句歌詞，我去查了那首歌，聽了一整晚。"}, {"y": [2012, 2040], "text": "{n}每天都傳 LINE 問我早餐吃什麼。有一天{p}沒傳，我整個早上一直看手機。"}, {"y": [2012, 2040], "text": "我們的聊天紀錄已經滑不到最上面了。朋友問我們現在是什麼關係，我答不出來。"}, {"text": "朋友起鬨說我們很配。{n}笑著說「哪有」，可是沒有否認。"}, {"text": "{n}說剛好要去我家附近，順路送我回去。後來我才知道，{p}家在完全相反的方向。"}, {"text": "我們又單獨出去吃了一次飯。結帳的時候搶著付錢，最後說好下次換我請。"}, {"text": "{n}記得我說過不吃香菜。點菜的時候，{p}很自然地跟老闆說不要香菜。"}, {"y": [1975, 2040], "text": "下雨天，{n}只帶了一把傘。我們撐著同一把傘走到車站，兩個人的肩膀都濕了一半。"}, {"text": "我開始會注意{n}今天穿什麼。有一次{p}剪了頭髮，我是第一個發現的。"}], "ask": [{"text": "我跟{n}已經單獨出去好幾次了。朋友問我們是不是在一起了，我說還沒。"}, {"text": "送我回家的路上，{n}走得很慢。到了巷口，{p}停下來，好像有話要說，最後只說了晚安。"}, {"text": "我發現自己每天都在等{n}的消息。{p}晚一點回，我就整晚靜不下來。"}, {"text": "這幾個月，我跟{n}幾乎每天都會聯絡。我開始想，要不要把話說清楚。"}, {"text": "{n}的朋友見到我，都會對我笑一下。我想，{p}大概跟朋友提過我。"}], "fade": [{"text": "後來{n}越來越少回我。我們沒有吵架，也沒有說清楚，就這樣淡了。"}, {"text": "{n}說最近比較忙。忙了一個月以後，我們就沒有再約了。"}, {"text": "我聽說{n}跟別人在一起了。我們本來就還不算什麼，我卻難過了好幾天。"}, {"y": [2009, 2040], "text": "我們還是會互相按讚，但再也沒有單獨出去過。"}, {"y": [1961, 2008], "text": "我寫給{n}的信，過了很久才收到一封很短的回信。之後，我就沒有再寫了。"}]};/*CT_END*/
